INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('464f4265-168f-41ec-b5e7-1645b85e14e5','studio_characters','e3ed8aa4-6a04-4790-9eff-6a0c06066e35','Ife','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"e3ed8aa4-6a04-4790-9eff-6a0c06066e35","name":"Ife","media":{"tbdFields":"Birth date\nExact chronological age\nWeight\nNationality\nPartner\nChildren\nNamed non-family allies\nNamed personal enemies","canonLocks":"Deep warm-brown skin\nCosmic pink eyes\nNatural black 4C hair\nLong decorated braids\nAthletic-curvaceous build\nSteam Rose signature color\nBronze and copper accessories\nBone Dragon Whip\nPink Steam Dragon true form\nIridescent wing membranes\nSteam and bubble magic","galleryUrl":"","mediaNotes":"Maintain visual continuity across all future artwork and 3D models. Pink should remain Ife''s dominant supernatural color, supported by bronze, copper, violet, pearl, and subtle iridescent blue.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/portrait/1790355886982-ife-character-portrait-2.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nBone Dragon Whip Reference — Done\nVRoid Turnaround Reference — Done\nBlender Model Reference — Done","productionNotes":"Use the established Reference / Production Sheet as the primary visual guide. Preserve Ife''s deep warm-brown complexion, cosmic pink eyes, long decorated 4C braids, athletic-curvaceous build, pink steam-woven clothing, bronze jewelry, and pink-centered elemental effects.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/reference/1790355900799-ife-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/alternate/1790355917413-ife-alternate-true-form.png"},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ife","race":"Dragon","alias":"The Pink Steam Dragon","gender":"Female","titles":"Daughter of Fire and Water\nProtector of the Scalding Gardens\nThe Steam-Born Guardian","subrace":"Steam Dragon","summary":"Ife is the Pink Steam Dragon, born from the union of Ignis and Leviathans. Fire and Water combine within her as Steam, giving her command over superheated vapor, pressure, condensation, and supernatural bubbles. Quiet and protective by nature, she specializes in defending others and controlling the battlefield.","heritage":"African + Asian","homeland":"Ignis Peaks","pronouns":"She/Her","birthDate":"","nicknames":"Pink Steam","occupation":"Elemental Guardian","affiliation":"Ignis Peaks","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"Love","nationality":"","spoilerLevel":"","pronunciation":"EE-feh","currentResidence":"Moltenmaw Caverns","elementalHeritage":"Fire + Water"},"abilities":{"weapons":"Bone Dragon Whip","strengths":"Battlefield control\nDefensive versatility\nThermal resistance\nPressure manipulation\nEnvironmental adaptability\nWeapon synergy\nHigh elemental output\nProtective focus","weaknesses":"Extreme cold\nMoisture-depleted environments\nOverpressure\nProtective exploitation\nEmotional pressure","combatStyle":["Defensive zoning","Battlefield control","Mid-range whip combat","Containment","Counterattacking","Circular movement"],"limitations":["Steam requires elemental balance","Bubble durability is finite","Large bubbles consume more energy","Pressure releases can endanger allies","Large-scale techniques require concentration","Dragon form increases energy consumption"],"powerSource":["Primordial elemental bloodline","Fire","Water","Steam"],"abilityNotes":"Steam is Ife''s unique elemental identity rather than separate Fire and Water spellcasting. Fire manifests primarily as heat, Water as moisture and condensation, and their equilibrium produces Steam. Her bubbles act as supernatural pressure membranes capable of defense, containment, transportation, and storing extreme heat or pressure.","combatProfile":"Ife controls space through her Bone Dragon Whip, steam fields, reinforced bubbles, and pressure attacks. She prefers to contain threats, protect allies, and punish attempts to breach her defensive perimeter. Her fighting style becomes significantly more destructive when someone under her protection is threatened.","weaponDetails":"Ruchika crafted the Bone Dragon Whip from a replica of his own tail-bone structure. Its articulated bone segments are flexible, heat-resistant, self-repairing, and attuned to Ife. She can channel superheated steam through its internal structure for binding, striking, and pressure-based attacks.","transformations":"Pink Steam Dragon\nSteam Surge\nPressure-Crowned Dragon State","primaryAbilities":"Superheated Steam Generation\nSteam Manipulation\nBubble Sorcery\nThermal Pressure Manipulation\nExtreme Thermal Resistance\nElemental Condensation","secondaryAbilities":"Steam Veil\nHeat Shimmer\nBubble Platforms\nSteam Propulsion\nPressure Detection\nCondensation Tracking\nLava Encapsulation","signatureTechniques":"Steam Lash\nScalding Bind\nPressure Spike\nSteam Whip Cyclone\nBubble Prison\nGuardian Bubble\nPinkout\nScalding Garden\nLava Bloom\nScalding Veil","transformationDetails":"Ife''s true form is a massive deep rose-pink Steam Dragon with translucent underlayers, obsidian-edged markings, cosmic pink eyes, and iridescent bubble-film wing membranes. Her transformation is concealed within rapidly expanding steam as scales, claws, tail, and wings emerge. Pressure-Crowned Dragon State is a high-output state of her true form rather than a separate transformation."},"is_public":false,"appearance":{"build":["Athletic","Curvaceous","Strong thighs","Defined shoulders","Hourglass proportions"],"nails":["Almond-shaped","Dusty rose","Deep rose accents","Pearl highlights"],"eyeHex":["Main Iris Pink — #E75C9A","Deep Iris — #8E285E","Light Iris Pink — #FF8FC5","Galaxy Violet — #9C68D7","Magical Glow — #FFD0EA","Outer Iris Ring — #6F204E","Hot-Pink Ring — #FF72B6","Pupil — #291224"],"height":"5''8\" / 173 cm","makeup":["Burnt rose blush","Deep plum eyeshadow","Rose mauve eyeshadow","Iridescent pink eyelids","Pearl-pink eye highlights","Black-plum eyeliner","Smoky burgundy lower lash","Deep berry-brown lip liner","Burnt rose lips","Bubble-pearl lip highlight"],"weight":"","hairHex":["Primary Hair — #171116","Warm Black — #24191D","Brown Highlight — #49302F","Pink Reflection — #8B405F"],"skinHex":["Deep Mahogany — #6B3B32","Warm Brown — #805044","Warm Highlight — #A96E5D","Bright Highlight — #C58B78","Shadow — #45241F","Deep Shadow — #2A1615"],"eyeColor":["Cosmic pink","Iridescent pink-violet"],"grooming":"Meticulous hair, skin, jewelry, and clothing care.","skinTone":["Deep warm brown","Reddish-mahogany undertone"],"wardrobe":"Ignis Peaks casual wear\nSunna resting attire\nCombat attire\nCeremonial attire\nSunken Dominion attire","hairColor":["Natural black"],"hairStyle":"Long decorated braids with a raised braided crown and bun.","accessories":"Bronze hoop earrings\nPink gemstone earrings\nForehead jewelry\nHead chains\nHair rings\nPink hair beads\nBronze braid cuffs\nLayered necklaces\nChoker\nUpper-arm cuffs\nBracelets\nWrist cuffs\nWaist chains\nDecorative belt\nHip chains\nAnklets\nPink gemstones","faceDetails":["Softly angular oval face","High cheekbones","Defined jawline","Full lips","Softly broad nose","Almond-shaped eyes","Thick natural eyebrows","Long dark eyelashes"],"hairTexture":["4C","Dense","Tightly coiled"],"colorPalette":"Deep Mahogany — #6B3B32\nWarm Brown — #805044\nDragon Black — #171116\nSteam Rose — #C77B91\nCosmic Pink — #E75C9A\nBubble Blush — #E5A7B8\nSteam Pearl — #F2CAD5\nPressure Rose — #87485F\nBubble Violet — #9C68D7\nBubble Blue — #82C9DF\nDragon Bronze — #9B633B\nMolten Copper — #B96E46\nSteam Gold — #D9A568\nVolcanic Black — #21191C","dominantHand":"Right","outfitColors":"Dusty Steam Pink — #C77B91\nLight Rose — #E5A7B8\nPearl Pink — #F2CAD5\nDeep Rose — #87485F\nWarm Cream — #E8D3C0\nBronze — #9B633B\nCopper — #B96E46\nGold — #D9A568\nPink Gemstone — #D9568D\nBubble Violet — #B894E8\nBubble Blue — #82C9DF","alternateForm":["Pink Steam Dragon"],"clothingStyle":"Flowing early-medieval fantasy attire influenced by African and Sahelian silhouettes. Draped fabrics, split panels, wrapped garments, metallic body jewelry, and translucent steam-woven textiles emphasize movement and bubble motifs.","appearanceNotes":"Ife''s design visually balances Fire and Water through warm skin, bronze metals, flowing fabrics, iridescence, moisture, and translucent bubble motifs. Pink is her dominant supernatural color. Her magical activity increases the visibility of steam, bubbles, iridescent markings, and heat distortion.","outfitMaterials":["Steam-woven alchemical silk","Translucent magical fibers","Bronze","Copper","Pink gemstones"],"postureMovement":["Upright","Composed","Fluid","Deliberate","Circular combat movement"],"signatureOutfit":"A wrapped pink upper garment with layered asymmetrical skirt panels, translucent steam-woven fabric, a decorated metallic belt, and bronze body jewelry.","distinguishingFeatures":["Cosmic pink irises","Long decorated braids","Pink steam aura","Iridescent power markings","Heat shimmer"]},"created_at":"2026-09-25T16:39:50.039916+00:00","updated_at":"2026-09-25T17:12:39.42624+00:00","is_complete":false,"origin_lore":{"fears":["Failing to protect loved ones","Losing family","Losing emotional control"],"goals":["Master Steam magic","Understand her dual heritage","Find answers about Rahim","Protect without controlling"],"beliefs":["Strength should protect","Opposing forces can coexist","Power requires purpose","Balance creates strength"],"culture":["Ignis Peaks","Sunken Dominion","Primordial Dragonkin"],"lineage":"Primordial Fire and Water bloodline","storyArc":"Ife''s arc explores the difference between protecting others and believing she is responsible for everything that happens to them. Rahim''s disappearance challenges her belief that sufficient strength can always keep family safe. Her eventual discovery of Ash further forces her to accept that she cannot protect someone from circumstances she never knew existed.","backstory":"Born to Ignis and Leviathans, Ife emerged as a natural equilibrium between Fire and Water. Rather than inheriting two separate elemental disciplines, their opposing forces fused within her as Steam. She grew into a protective fighter who favors containment and defense, later receiving the Bone Dragon Whip from Ruchika. Rahim''s disappearance remains an unresolved emotional wound, while the existence of Ash remains unknown to her.","childhood":"Ife grew up within Moltenmaw Caverns, where volcanic heat and lava were natural parts of everyday life. She developed a strong attachment to the Sunna and learned early that she could sleep beneath its molten surface. Her childhood training focused heavily on controlling the heat, moisture, and pressure generated by her Steam Dragon physiology.","lifestyle":["Lives in Moltenmaw Caverns","Sleeps beneath the Sunna","Maintains her braids","Maintains her weapon","Practices steam control","Trains with family","Enjoys solitude"],"storyRole":"Ife serves as an Elemental Guardian and relational bridge between multiple Primordial bloodlines. Her Fire and Water heritage places her near the center of the wider elemental family while her protective nature makes her a stabilizing presence during conflict.","birthplace":"Moltenmaw Caverns","psychology":["Protective instinct","Strong emotional restraint","Over-responsibility","Difficulty accepting protection","Need for stability"],"motivations":["Protect her family","Protect the vulnerable","Maintain balance"],"personality":["Warm","Reserved","Observant","Protective","Dependable","Patient","Practical","Family-oriented","Responsible","Quietly affectionate","Stubborn"],"voiceSpeech":["Warm medium-low voice","Measured speech","Direct wording","Dry humor","Quiet when angry"],"likesDislikes":["Likes extreme warmth","Likes hot springs","Likes steam","Likes rain on warm stone","Likes quiet mornings","Likes family gatherings","Likes routine","Likes jewelry","Likes bubbles","Likes swimming","Dislikes needless cruelty","Dislikes betrayal","Dislikes reckless endangerment","Dislikes unnecessary chaos","Dislikes bullying"],"majorLifeEvents":"Birth of the Pink Steam Dragon\nChildhood in Moltenmaw Caverns\nDiscovery of the Sunna\nMastery of Bubble Sorcery\nTraining under Ignis\nReceiving the Bone Dragon Whip\nRahim''s disappearance"},"canon_status":"concept","current_step":3,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/portrait/1790355886982-ife-character-portrait-2.png","relationships":{"allies":"","rivals":"Ezra","enemies":"","mentors":"Ignis\nLeviathans\nRuchika","parents":"Ignis\nLeviathans","partner":"","children":"","siblings":"Rahim\nRuchika\nEzra\nAsh","worldConnections":"Ignis Peaks\nMoltenmaw Caverns\nSunken Dominion\nSunna","relationshipNotes":"Ife is deeply family-oriented and often assumes a protective role around those she loves. Rahim''s disappearance remains a major emotional wound. Ruchika created her Bone Dragon Whip, while Ezra shares a competitive sibling rivalry with her. Ife does not currently know that Ash exists."},"spoiler_level":"private","race_record_id":"1ec72d01-822b-4992-9434-7772a6b4e474","realm_record_id":"97d4dc51-d1bf-4f80-9e77-3955ba9dad35","workflow_status":"draft","family_record_id":"08d087d1-5f3c-4b76-9ee9-2917fe667bf1","faction_record_id":"406ddfbf-feab-4b20-9026-bd74b716fbda"}','2026-09-25T17:12:43.745673+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('c3a2a44e-7e3b-4443-a427-92d60512db8e','studio_characters','35fd725a-f7b0-45a0-acc8-61958469e015','Nysera Sylvaris','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"35fd725a-f7b0-45a0-acc8-61958469e015","name":"Nysera Sylvaris","media":{"tbdFields":"","canonLocks":"Pure Sylvani Elf\nStrong resemblance to Shailara\nAmber-brown left eye\nGlacial icy-blue right eye\nLong wild dark-brown hair\nMoss-green hair highlights\nLight bronze skin\nVine-like markings\nDark emerald marking glow\nBriarfang","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/portrait/1790356295017-nysera-sylvaris-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"Preserve Nysera''s strong facial resemblance to Shailara while maintaining her fully Sylvani identity and wilder visual language. Her heterochromia, dark wild hair, moss-green highlights, light bronze skin, and vine-like markings are essential visual identifiers.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/reference/1790356310666-nysera-sylvaris-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/alternate/1790356321872-nysera-sylvaris-2-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Nysera Sylvaris","race":"Sylvani Elf","alias":"The Wild Root","gender":"Female","titles":"The Thornheart Elf\nThe Shadow of Eldoria\nKeeper of the Hollow Groves\nBeloved Sister of Shailara, The Living Mountain","subrace":"","summary":"Nysera Sylvaris is a pure Sylvani Elf known as the Wild Root and Keeper of the Hollow Groves. Where Shailara embodies calm growth and sheltering nature, Nysera represents nature''s untamed, darker will. Her chaotic temperament and forbidden-feeling Hollow Root magic make her both a troublesome presence and a potential guardian of Eldoria.","heritage":"Sylvani","homeland":"Eldoria","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Eldoria","elementalHeritage":""},"abilities":{"weapons":"Briarfang","strengths":"Unpredictable combat\nEnvironmental control\nExceptional mobility\nImprovisation\nMagical energy draining\nAdaptive weapon use","weaknesses":"","combatStyle":["Wild","Chaotic","Improvised","Acrobatic","Feral"],"limitations":"","powerSource":["The Hollow Root","Sylvani nature magic"],"abilityNotes":"The Hollow Root governs the neglected and darker aspects of nature rather than conventional nurturing growth. Gravebloom causes black flowers to erupt from the ground and drain magical energy, with stronger opponents producing larger blooms. Thornshade Forest transforms the surrounding area into black trees, twisting roots, glowing fungi, and dark vines that obey Nysera.","combatProfile":"Nysera fights more like a feral woodland spirit than a Sylvani noble. She jumps, spins, climbs, and exploits the environment while using roots for sudden movement and unconventional attacks. Her unpredictability makes her difficult to read in battle.","weaponDetails":"Briarfang is a living weapon formed from enchanted black roots. It can transform between whip, spear, bow, and blade configurations according to Nysera''s needs and mood.","transformations":"","primaryAbilities":"Dead Forest Manipulation\nBlack Root Manipulation\nFungal Manipulation\nThorn Growth\nDecay Cycle Manipulation\nShadowed Vegetation Manipulation","secondaryAbilities":"Root Mobility\nRoot Slingshot Movement\nVegetation Command","signatureTechniques":"Gravebloom\nThornshade Forest","transformationDetails":""},"is_public":false,"appearance":{"build":"","nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Amber-brown left eye","Glacial icy-blue right eye"],"grooming":"Wild and natural","skinTone":["Light bronze"],"wardrobe":"","hairColor":["Dark brown","Near-black undertones","Moss-green highlights"],"hairStyle":"Long, wild, usually unbrushed","accessories":"","faceDetails":["Elegant jawline","High cheekbones","Graceful Sylvani features"],"hairTexture":"","colorPalette":"Dark brown\nNear-black\nMoss green\nDark emerald\nAmber-brown\nIcy blue","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"Nysera strongly resembles Shailara, sharing the same elegant facial structure and graceful Sylvani features. Outsiders sometimes mistake them for twins or assume they share the same father, which secretly delights Nysera. Her moss-green hair streaks become visible in sunlight, while her vine-like markings glow dark emerald when she channels magic.","outfitMaterials":"","postureMovement":["Restless","Energetic","Acrobatic","Feral"],"signatureOutfit":"","distinguishingFeatures":["Heterochromia","Faint vine-like markings","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:47:28.813169+00:00","updated_at":"2026-09-25T17:12:05.967313+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Decay is part of nature","Untamed nature deserves protection"],"culture":["Sylvani"],"lineage":"Pure Sylvani","storyArc":"","backstory":"Nysera inherited no Terrax blood and is entirely Sylvani. Despite this, her strong resemblance to Shailara frequently causes outsiders to assume the sisters share the same father. Her unusual connection to the darker cycles of nature distinguishes her from traditional Sylvani and leaves Eldoria''s elders divided over what she may become.","childhood":"","lifestyle":["Climbs constantly","Explores wild places","Rarely sits still"],"storyRole":"Nysera serves as Eldoria''s unpredictable troublemaker and a possible future guardian. Her connection to neglected and feared aspects of nature challenges traditional Sylvani ideas about what natural magic should be.","birthplace":"Eldoria","psychology":["Idolizes Shailara","Constantly seeks stimulation","Enjoys pushing back","Intensely loyal"],"motivations":["Protect Shailara","Defend untamed nature","Follow her own instincts"],"personality":["Hyperactive","Feisty","Stubborn","Protective","Reckless","Talented","Argumentative","Distractible"],"voiceSpeech":["Energetic","Argumentative","Blunt"],"likesDislikes":["Collecting flowers Shailara touched","Sketching Shailara","Bragging about Shailara","Dislikes insults toward Shailara","Dislikes being told no"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/portrait/1790356295017-nysera-sylvaris-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"Shailara","worldConnections":"Eldoria","relationshipNotes":"Nysera intensely adores and idolizes Shailara. She collects flowers Shailara has touched, keeps sketches of her, constantly brags about her, and readily starts fights when someone insults her. Shailara is one of the few people capable of calming Nysera down."},"spoiler_level":"private","race_record_id":"76da8c54-5f55-4b33-b807-02e8eb74e869","realm_record_id":"291c05cb-0705-495d-95be-c6037453f9b4","workflow_status":"draft","family_record_id":"00ba4f50-602d-4833-9eae-2ce8c18297e6","faction_record_id":null}','2026-09-25T17:13:02.924652+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('44a3f077-d105-45bf-a49a-fd01d50bfd64','studio_characters','35fd725a-f7b0-45a0-acc8-61958469e015','Nysera Sylvaris','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"35fd725a-f7b0-45a0-acc8-61958469e015","name":"Nysera Sylvaris","media":{"tbdFields":"","canonLocks":"Pure Sylvani Elf\nStrong resemblance to Shailara\nAmber-brown left eye\nGlacial icy-blue right eye\nLong wild dark-brown hair\nMoss-green hair highlights\nLight bronze skin\nVine-like markings\nDark emerald marking glow\nBriarfang","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/portrait/1790356295017-nysera-sylvaris-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"Preserve Nysera''s strong facial resemblance to Shailara while maintaining her fully Sylvani identity and wilder visual language. Her heterochromia, dark wild hair, moss-green highlights, light bronze skin, and vine-like markings are essential visual identifiers.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/reference/1790356310666-nysera-sylvaris-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/alternate/1790356321872-nysera-sylvaris-2-alternate-true-form.png"},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Nysera Sylvaris","race":"Sylvani Elf","alias":"The Wild Root","gender":"Female","titles":"The Thornheart Elf\nThe Shadow of Eldoria\nKeeper of the Hollow Groves\nBeloved Sister of Shailara, The Living Mountain","subrace":"","summary":"Nysera Sylvaris is a pure Sylvani Elf known as the Wild Root and Keeper of the Hollow Groves. Where Shailara embodies calm growth and sheltering nature, Nysera represents nature''s untamed, darker will. Her chaotic temperament and forbidden-feeling Hollow Root magic make her both a troublesome presence and a potential guardian of Eldoria.","heritage":"Sylvani","homeland":"Eldoria","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Eldoria","elementalHeritage":""},"abilities":{"weapons":"Briarfang","strengths":"Unpredictable combat\nEnvironmental control\nExceptional mobility\nImprovisation\nMagical energy draining\nAdaptive weapon use","weaknesses":"","combatStyle":["Wild","Chaotic","Improvised","Acrobatic","Feral"],"limitations":"","powerSource":["The Hollow Root","Sylvani nature magic"],"abilityNotes":"The Hollow Root governs the neglected and darker aspects of nature rather than conventional nurturing growth. Gravebloom causes black flowers to erupt from the ground and drain magical energy, with stronger opponents producing larger blooms. Thornshade Forest transforms the surrounding area into black trees, twisting roots, glowing fungi, and dark vines that obey Nysera.","combatProfile":"Nysera fights more like a feral woodland spirit than a Sylvani noble. She jumps, spins, climbs, and exploits the environment while using roots for sudden movement and unconventional attacks. Her unpredictability makes her difficult to read in battle.","weaponDetails":"Briarfang is a living weapon formed from enchanted black roots. It can transform between whip, spear, bow, and blade configurations according to Nysera''s needs and mood.","transformations":"","primaryAbilities":"Dead Forest Manipulation\nBlack Root Manipulation\nFungal Manipulation\nThorn Growth\nDecay Cycle Manipulation\nShadowed Vegetation Manipulation","secondaryAbilities":"Root Mobility\nRoot Slingshot Movement\nVegetation Command","signatureTechniques":"Gravebloom\nThornshade Forest","transformationDetails":""},"is_public":false,"appearance":{"build":"","nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Amber-brown left eye","Glacial icy-blue right eye"],"grooming":"Wild and natural","skinTone":["Light bronze"],"wardrobe":"","hairColor":["Dark brown","Near-black undertones","Moss-green highlights"],"hairStyle":"Long, wild, usually unbrushed","accessories":"","faceDetails":["Elegant jawline","High cheekbones","Graceful Sylvani features"],"hairTexture":"","colorPalette":"Dark brown\nNear-black\nMoss green\nDark emerald\nAmber-brown\nIcy blue","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"Nysera strongly resembles Shailara, sharing the same elegant facial structure and graceful Sylvani features. Outsiders sometimes mistake them for twins or assume they share the same father, which secretly delights Nysera. Her moss-green hair streaks become visible in sunlight, while her vine-like markings glow dark emerald when she channels magic.","outfitMaterials":"","postureMovement":["Restless","Energetic","Acrobatic","Feral"],"signatureOutfit":"","distinguishingFeatures":["Heterochromia","Faint vine-like markings","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:47:28.813169+00:00","updated_at":"2026-09-25T17:13:02.924652+00:00","is_complete":false,"origin_lore":{"fears":"","goals":"","beliefs":["Decay is part of nature","Untamed nature deserves protection"],"culture":["Sylvani"],"lineage":"Pure Sylvani","storyArc":"","backstory":"Nysera inherited no Terrax blood and is entirely Sylvani. Despite this, her strong resemblance to Shailara frequently causes outsiders to assume the sisters share the same father. Her unusual connection to the darker cycles of nature distinguishes her from traditional Sylvani and leaves Eldoria''s elders divided over what she may become.","childhood":"","lifestyle":["Climbs constantly","Explores wild places","Rarely sits still"],"storyRole":"Nysera serves as Eldoria''s unpredictable troublemaker and a possible future guardian. Her connection to neglected and feared aspects of nature challenges traditional Sylvani ideas about what natural magic should be.","birthplace":"Eldoria","psychology":["Idolizes Shailara","Constantly seeks stimulation","Enjoys pushing back","Intensely loyal"],"motivations":["Protect Shailara","Defend untamed nature","Follow her own instincts"],"personality":["Hyperactive","Feisty","Stubborn","Protective","Reckless","Talented","Argumentative","Distractible"],"voiceSpeech":["Energetic","Argumentative","Blunt"],"likesDislikes":["Collecting flowers Shailara touched","Sketching Shailara","Bragging about Shailara","Dislikes insults toward Shailara","Dislikes being told no"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/portrait/1790356295017-nysera-sylvaris-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"Shailara","worldConnections":"Eldoria","relationshipNotes":"Nysera intensely adores and idolizes Shailara. She collects flowers Shailara has touched, keeps sketches of her, constantly brags about her, and readily starts fights when someone insults her. Shailara is one of the few people capable of calming Nysera down."},"spoiler_level":"private","race_record_id":"76da8c54-5f55-4b33-b807-02e8eb74e869","realm_record_id":"291c05cb-0705-495d-95be-c6037453f9b4","workflow_status":"draft","family_record_id":"00ba4f50-602d-4833-9eae-2ce8c18297e6","faction_record_id":null}','2026-09-25T17:13:05.52667+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('9288b6bf-a800-4eb8-913b-3b2886723781','studio_characters','bc34fdb8-22a5-439b-8067-e5b670626b0f','Shailara','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"bc34fdb8-22a5-439b-8067-e5b670626b0f","name":"Shailara","media":{"tbdFields":"Birth date\nAge\nHeight\nWeight\nBirthplace\nCurrent residence\nOccupation\nMother''s name","canonLocks":"Warm bronze-brown skin\nJade green eyes\nDark brown hair\nEmerald hair undertones\nPointed Sylvani ears\nLiving vines in hair\nNatural flowers in hair\nForest-green signature outfit\nEmerald crystal motifs\nLiving stone dragon form","galleryUrl":"","mediaNotes":"Established visual references include Shailara''s human portrait, Earth Dragon form, and full visual production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/portrait/1790356221787-shailara-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Preserve the established human and dragon designs. Her visual identity should consistently combine stone, emerald crystal, living vegetation, refined Sylvani elements, and Sunspear Indian heritage.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/reference/1790356235758-shailara-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/alternate/1790356241924-shailara-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Shailara","race":"Half Earth Dragon / Half Sylvani Elf","alias":"The Living Mountain","gender":"Female","titles":"The Living Mountain\nKeeper of the Emerald Vein","subrace":"","summary":"Shailara is the daughter of Terrax, an Earth Dragon of Sunspear Indian heritage, and a Sylvani Elf deeply connected to nature and traditional arcane magic. Known as the Living Mountain, she embodies a rare union of ancient stone and living nature. Her earth-dragon power manifests through the Emerald Vein, allowing stone, crystal, roots, and vegetation to exist as parts of the same living system.","heritage":"Indian + Sylvani Elf","homeland":"","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"Stone Blossom","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Earth + Sylvani"},"abilities":{"weapons":"","strengths":"Earth manipulation\nEnvironmental restoration\nDefensive durability\nTerrain control\nNature synergy","weaknesses":"","combatStyle":["Terrain control","Defensive combat","Environmental manipulation"],"limitations":"","powerSource":["Earth Dragon heritage","Sylvani magic","Emerald Vein"],"abilityNotes":"The Emerald Vein unifies Shailara''s earth and Sylvani inheritances, allowing stone and plant life to function together. Her Lithobloom Core causes vegetation to grow naturally from her draconic body and allows her presence to encourage ecological renewal.","combatProfile":"Shailara reshapes the battlefield through stone, roots, crystals, and rapidly growing vegetation. Her fighting style emphasizes environmental control and defense rather than reckless aggression. In dragon form, her immense stone body provides exceptional physical durability.","weaponDetails":"","transformations":"Earth Dragon Form","primaryAbilities":"Stone Manipulation\nCrystal Manipulation\nPlant Manipulation\nRoot Manipulation\nLand Restoration","secondaryAbilities":"Accelerated Plant Growth\nCrystal Growth\nLiving Stone Creation\nEcosystem Restoration\nStone-to-Wood Transmutation","signatureTechniques":"Emerald Vein\nLithobloom Core","transformationDetails":"Shailara transforms into a colossal Earth Dragon resembling a living mountain. Her body is covered in layered stone scales with moss, vines, flowers, and emerald crystal formations growing naturally across her frame. Her wings resemble interlocking petrified leaves, stone structures, and crystal branches."},"is_public":false,"appearance":{"build":["Tall","Graceful","Curvaceous"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Jade green"],"grooming":"","skinTone":["Warm bronze-brown"],"wardrobe":"Sylvani gowns\nNature-inspired ceremonial attire","hairColor":["Dark brown","Emerald undertones"],"hairStyle":"Long and flowing","accessories":"Emerald forehead jewel\nEmerald earrings\nGold jewelry\nLiving floral ornaments","faceDetails":["Elegant features","High cheekbones","Pointed ears"],"hairTexture":["Thick","Wavy"],"colorPalette":"Granite Grey\nMoss Green\nJade\nEmerald\nOlive\nEarth Brown\nSoft Gold\nIvory\nBlossom Pink","dominantHand":"","outfitColors":"Forest green\nEmerald\nIvory\nSoft gold","alternateForm":["Earth Dragon Form"],"clothingStyle":"Elegant Sylvani clothing blending natural materials, botanical motifs, flowing fabrics, gemstones, and refined ornamentation.","appearanceNotes":"Her human form visibly blends Sunspear Indian and Sylvani features. Living vegetation naturally grows among her hair and clothing. Her dragon form resembles a living mountain composed of layered stone scales, vegetation, vines, flowers, and emerald crystal growths.","outfitMaterials":["Layered fabric","Living vines","Gold ornamentation","Emerald gemstones"],"postureMovement":["Graceful","Composed"],"signatureOutfit":"An elegant forest-green Sylvani gown with botanical detailing, soft flowing ivory fabric, gold ornamentation, emerald accents, and living vines woven naturally through the design.","distinguishingFeatures":["Living vines in hair","Natural flowers in hair","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:49:43.887688+00:00","updated_at":"2026-09-25T17:11:19.195575+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Life can return","Stone can nurture growth"],"culture":["Sunspear","Sylvani"],"lineage":"Terrax + Sylvani Elf","storyArc":"","backstory":"Born from an Earth Dragon and a Sylvani Elf, Shailara inherited Terrax''s connection to stone alongside her mother''s affinity for nature and traditional arcane magic. These inheritances developed together rather than remaining separate, producing her unusual bond with living stone.","childhood":"","lifestyle":["Nature-oriented"],"storyRole":"","birthplace":"","psychology":["Values renewal","Protective of nature","Emotionally grounded"],"motivations":["Protect living ecosystems","Restore damaged land","Preserve natural balance"],"personality":["Calm","Nurturing","Patient","Compassionate","Protective","Hopeful"],"voiceSpeech":["Calm","Measured","Gentle"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/portrait/1790356221787-shailara-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Terrax","partner":"","children":"","siblings":"Nysera","worldConnections":"","relationshipNotes":"Shailara and Nysera share the same Sylvani mother but have different fathers. Nysera is a full Sylvani Elf and is intensely devoted to Shailara."},"spoiler_level":"private","race_record_id":"41d87f15-5819-4dbb-a9db-7abbdc65e92b","realm_record_id":null,"workflow_status":"draft","family_record_id":"e0563851-b12b-4a90-827f-5c38b92a4a58","faction_record_id":null}','2026-09-25T17:13:18.46252+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('a352579e-73e4-4528-8ebc-4c0a632130d3','studio_characters','231f402f-3543-4506-a286-8bd29c6974e1','Ezra','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"231f402f-3543-4506-a286-8bd29c6974e1","name":"Ezra","media":{"tbdFields":"","canonLocks":"Alias: The Sapphire Dragon\nLight caramel skin\nDruskari-African + Faelite-White heritage\nSapphire blue eyes\nBlack and silver-white hair\nSapphire blue primary palette\nLightning element\nFire + Air elemental heritage\nCrystalline dragon scales\nStorm-cloud dragon wings\nAnime visual style","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Use the established anime production-sheet design as Ezra''s primary visual reference. Human and dragon artwork should emphasize sapphire blue, stark white, silver, black, crystalline shapes, and electrical effects. His human appearance must retain his light caramel complexion and mixed Druskari-African and Faelite-White features.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ezra","race":"Elemental Dragon","alias":"The Sapphire Dragon","gender":"Male","titles":"Lightning Prince","subrace":"","summary":"Ezra, known as the Sapphire Dragon, is a Lightning Dragon born from the union of primal Fire and Air. Brilliant, volatile, and exceptionally fast, he embodies the friction between heat and atmosphere. He carries himself like a high-born prince and openly considers his speed, power, and lineage proof that he is destined for greatness.","heritage":"Druskari-African + Faelite-White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Air"},"abilities":{"weapons":"","strengths":"Extreme speed\nExplosive offense\nAerial mobility\nRapid strikes\nElectrical paralysis\nPlasma attacks\nStorm manipulation","weaknesses":"Arrogance\nImpatience\nPoor defensive patience\nEasily provoked\nOverconfidence","combatStyle":["High-speed offense","Rapid-hit combat","Aerial combat","Hit-and-run attacks","Showboating","Electrical suppression"],"limitations":["Favors offense over defense","Can underestimate slower opponents"],"powerSource":["Primal Fire","Primal Air","Lightning"],"abilityNotes":"Ezra''s Lightning element results from the interaction of Fire and Air. He can manipulate electrical currents and plasma, create localized storms, electrify his claws, and generate enormous static charges. His movement can produce sonic cracks, and Lightning Shift allows brief transitions into electrical energy.","combatProfile":"Ezra fights through overwhelming speed and relentless offensive pressure. He circles opponents, attacks from rapidly changing angles, and uses electrical shocks to disrupt movement before delivering additional strikes. He prefers humiliating opponents through superior speed rather than patiently wearing them down.","weaponDetails":"","transformations":"Sapphire Dragon Form\nLightning Shift","primaryAbilities":"Lightning Manipulation\nElectrical Current Manipulation\nPlasma Manipulation\nLightning Generation\nStorm Generation","secondaryAbilities":"Extreme Speed\nElectrical Paralysis\nStatic Charge Generation\nAtmospheric Mobility\nEnergy Transformation","signatureTechniques":"Lightning Shift\nSonic Dash\nPlasma Burst\nElectrical Claws\nThunderstorm Summon","transformationDetails":"In Sapphire Dragon Form, Ezra becomes a sharp, aerodynamic dragon covered in brilliant electric-blue and stark-white crystalline scales. His anatomy favors jagged, streamlined shapes built for extreme aerial speed. Dark storm-cloud wings churn with internal lightning while electrical arcs continuously travel between his horns, spine, wings, and scales. Lightning Shift temporarily converts his body into electrical energy for near-instantaneous short-distance movement."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Athletic","Broad-shouldered"],"nails":"","eyeHex":["Sapphire Blue — #1261FF"],"height":"","makeup":"","weight":"","hairHex":["Black — #11131A","Silver-White — #E5E8F0"],"skinHex":["Light Caramel — #B98263"],"eyeColor":["Sapphire blue"],"grooming":"Immaculate","skinTone":["Light caramel"],"wardrobe":"Noble tunics\nLayered court attire\nElite champion armor\nLong coats\nArmored boots","hairColor":["Black","Silver-white"],"hairStyle":"Tousled two-tone hair","accessories":"Sapphire earrings\nDecorative chains\nSilver clasps\nArmored gauntlets","faceDetails":["Sharp jawline","Refined features","High cheekbones"],"hairTexture":["Thick","Wavy"],"colorPalette":"Sapphire Blue — #1261FF\nDeep Blue — #102B68\nMidnight Navy — #091426\nSilver — #C8CFDA\nStark White — #F4F5F7\nBlack — #11131A","dominantHand":"","outfitColors":"Sapphire blue\nDeep blue\nStark white\nSilver\nBlack","alternateForm":["Sapphire Dragon"],"clothingStyle":"Flashy high-born clothing inspired by early European court fashion and elite medieval champions. Ezra favors structured silhouettes, sweeping layers, luxurious detailing, and clothing designed to make his status immediately apparent.","appearanceNotes":"Ezra''s human design reflects his mixed Druskari-African and Faelite-White heritage. His light caramel complexion contrasts strongly with his sapphire, silver, white, and black palette. His overall appearance should remain handsome, sharp, aristocratic, and unmistakably confident.","outfitMaterials":["Fine woven fabric","Leather","Polished metal"],"postureMovement":["Confident","Regal","Quick","Explosive"],"signatureOutfit":"A high-born layered court ensemble combining sweeping noble tunics with fitted champion armor. Deep sapphire fabrics, stark white layers, silver detailing, structured shoulders, fitted gloves, and armored boots create a sharp princely silhouette.","distinguishingFeatures":["Split black and silver-white hair","Piercing gaze"]},"created_at":"2026-09-25T16:43:35.075732+00:00","updated_at":"2026-09-25T16:43:35.075732+00:00","is_complete":true,"origin_lore":{"fears":["Being overshadowed","Being proven inferior"],"goals":["Become the dominant heir","Earn unmatched recognition"],"beliefs":["Speed determines victory","Power deserves recognition","He is the rightful heir"],"culture":"","lineage":"Primal Fire Dragon + Primal Air Dragon","storyArc":"Ezra begins convinced that his speed, lineage, and spectacular power place him above his siblings. His rivalries increasingly confront him with abilities that cannot simply be overwhelmed by moving faster, forcing his certainty about superiority to be challenged.","backstory":"Ezra was born from the elemental union of Ignis and Atherous. Fire supplied the heat and raw energy of his nature, while Air supplied atmospheric movement and extraordinary speed. Their combination manifested in Ezra as Lightning, producing one of the family''s fastest and most visually explosive elemental descendants.","childhood":"","lifestyle":["Competitive","High-energy","Luxury-loving"],"storyRole":"Ezra serves as the brilliant family rival whose immense talent is complicated by pride and ambition. His competitive nature creates friction with siblings whose abilities challenge his belief that speed and overwhelming offense make him superior.","birthplace":"","psychology":["Massive ego","Craves recognition","Obsessed with superiority","Competitive with family","Equates speed with dominance"],"motivations":["Prove his superiority","Surpass his siblings","Claim personal glory","Honor his lineage"],"personality":["Arrogant","Loud","Proud","Competitive","Confident","Flashy","Ambitious","Easily insulted","Attention-seeking"],"voiceSpeech":["Confident","Boastful","Sharp","Provocative"],"likesDislikes":["Glory","Praise","Admiration","Speed","Competition","Luxury","Being underestimated","Losing","Slowness","Being ignored"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"Ife","enemies":"","mentors":"","parents":"Ignis\nAtherous","partner":"","children":"","siblings":"Ife\nRahim\nGaius\nAsh","worldConnections":"","relationshipNotes":"Ezra constantly provokes Ife and is frustrated by the durability of her defensive abilities. He respects Rahim''s raw power but dislikes his chaotic brutality. He considers Gaius boring and overly quiet despite their shared connection through Atherous. Ezra treats Ash with cold disdain because of Ash''s mortal maternal lineage and views him as a blemish on Ignis''s bloodline, unaware of how dangerous Ash''s smothering magic could be to his electricity."},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":null,"workflow_status":"draft","family_record_id":"a040ba80-3b84-4caf-b268-f0d59e8cbd2e","faction_record_id":null}','2026-09-25T17:14:43.75119+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('b0ff92ca-9582-4bfe-b962-a41030d9b98b','studio_characters','7e07c96b-9f3f-495f-b7b5-1e14cc4875f4','Rahim','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"7e07c96b-9f3f-495f-b7b5-1e14cc4875f4","name":"Rahim","media":{"tbdFields":"Birth date\nAge\nHeight\nWeight\nCurrent residence\nCurrent whereabouts\nOccupation\nAffiliation","canonLocks":"Mixed Black and Asian heritage\nDeep warm-brown skin\nBlack hair\nCrimson eyes\nTall muscular build\nBlack and crimson palette\nBlood-crystal aesthetic\nObsidian-black dragon scales\nGlowing crimson dragon veins\nAnime visual style","galleryUrl":"","mediaNotes":"The Reference / Production Sheet is the primary continuity reference for future Rahim artwork. Blood Dragon and blood-crystallization references establish his alternate-form visual language.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nBlood Crystallization Reference — Done","productionNotes":"Use the established anime production sheet as Rahim''s primary visual reference. Preserve his mixed Black and Asian facial identity, dark skin, black hair, crimson eyes, muscular build, black-and-crimson wardrobe, blood-crystal aesthetic, and established Blood Dragon design.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Rahim","race":"Elemental Dragon","alias":"The Blood Dragon","gender":"Male","titles":"Crimson Blood Dragon","subrace":"Blood Dragon","summary":"Rahim is the firstborn Blood Dragon of Ignis and Leviathans. Fire and Water manifest through him as chaotic blood magic, allowing him to manipulate life force, weaponize blood, and crystallize it into devastating constructs. Battle-hungry and arrogant, he considers many less destructive elemental powers beneath his own.","heritage":"Black + Asian","homeland":"Ignis Peaks","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Water"},"abilities":{"weapons":"Blood-crystal weapons","strengths":"Extreme destructive power\nBattlefield control\nVersatile blood constructs\nLife-force absorption\nBlood-crystal durability\nAggression amplification","weaknesses":"","combatStyle":["Aggressive","Overwhelming","Close-range combat","Battlefield domination","Construct-based combat"],"limitations":"","powerSource":["Fire","Water","Blood","Life force"],"abilityNotes":"Hemocrystal Dominion allows Rahim to condense manipulated blood into extremely hard crimson crystal for armor, weapons, spikes, and constructs. Bloodlust Amplification intensifies aggression and fighting spirit around him. Life-Force Siphon draws vitality from others, while Heart of the Battlefield allows spilled blood across a battlefield to become material for his constructs.","combatProfile":"Rahim thrives in prolonged, chaotic battles where blood and aggression are abundant. He combines direct physical combat with life-force manipulation, blood constructs, crystallized weapons, and large-scale battlefield control. His presence can intensify aggression around him, making an already violent conflict increasingly unstable.","weaponDetails":"Rahim crystallizes blood into blades, spears, shields, whips, armor, and other combat constructs. The weapons can be formed rapidly from manipulated blood and reshaped during battle.","transformations":"Blood Dragon Form\nCrimson Tyrant State","primaryAbilities":"Chaotic Blood Magic\nBlood Manipulation\nBlood Crystallization\nLife-Force Siphon\nBloodlust Amplification","secondaryAbilities":"Blood Construct Creation\nBlood-Crystal Armor\nBlood-Crystal Weaponry\nBlood-Crystal Regeneration","signatureTechniques":"Hemocrystal Dominion\nHeart of the Battlefield\nBlood Spear Storm","transformationDetails":"Rahim''s Blood Dragon Form has obsidian-black scales threaded with glowing crimson veins, scarlet eyes, blood-crystal structures, and wings formed through dark draconic tissue, blood mist, and crystal. In Crimson Tyrant State, blood crystallization spreads across his body as dense crimson armor, enlarging his horns, claws, spikes, and other natural weapons."},"is_public":false,"appearance":{"build":["Tall","Muscular","Broad-shouldered"],"nails":"","eyeHex":["Crimson — #A20D1A"],"height":"","makeup":"","weight":"","hairHex":["Black — #111014"],"skinHex":["Deep Brown — #704936"],"eyeColor":["Crimson red"],"grooming":"Clean-shaven","skinTone":["Deep warm brown"],"wardrobe":"Long black coat\nDark trousers\nCombat boots","hairColor":["Black"],"hairStyle":"Tousled medium-length hair","accessories":"Crimson pendant\nEarrings\nLayered chains\nRings","faceDetails":["Sharp jawline","High cheekbones","Strong brows"],"hairTexture":["Wavy","Thick"],"colorPalette":"Blood Crimson — #8A0712\nObsidian Black — #111014\nDeep Garnet — #5E101B\nMolten Scarlet — #D4232E","dominantHand":"","outfitColors":"Black\nCrimson\nDark red\nMetallic silver","alternateForm":["Blood Dragon Form","Crimson Tyrant State"],"clothingStyle":"Dark, regal battlewear combining draconic ornamentation with a dangerous and aristocratic silhouette.","appearanceNotes":"Rahim''s human design reflects his Black paternal and Asian maternal heritage. His established visual identity uses black, crimson, and blood-crystal accents. His dragon form is covered in obsidian-black scales threaded with glowing crimson veins and increasingly develops crystalline structures as his blood crystallization intensifies.","outfitMaterials":["Dark fabric","Leather","Metal","Blood crystal"],"postureMovement":["Confident","Predatory","Commanding"],"signatureOutfit":"Black battle attire with crimson accents, an open chest, layered dark fabrics, metallic detailing, and blood-crystal ornamentation.","distinguishingFeatures":["Dragon markings","Blood-crystal formations"]},"created_at":"2026-09-25T16:43:10.905895+00:00","updated_at":"2026-09-25T16:43:10.905895+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Power should be fully expressed"],"culture":"","lineage":"Firstborn of Ignis and Leviathans","storyArc":"Rahim''s established history connects him directly to Ash''s survival. After carrying out Hecate''s protective spell and delivering Ash to safety, he vanished under circumstances tied to altered memories, leaving his family without clear knowledge of his fate.","backstory":"Rahim is the eldest child of Ignis and Leviathans, with Fire and Water manifesting through him as Blood rather than Steam. He later carried out Hecate''s protective memory spell and delivered the infant Ash safely to Hecate''s great-aunt. Rahim subsequently vanished, leaving his whereabouts unknown and his memories altered.","childhood":"Rahim was raised at Ignis Peaks and developed a strong combat bond with Ignis.","lifestyle":"","storyRole":"Rahim is the volatile eldest sibling whose immense destructive potential contrasts sharply with the more controlled elemental expressions of his family. His disappearance and altered memories leave his current role unresolved.","birthplace":"Ignis Peaks","psychology":["Craves intense combat","Disdains weaker powers","Seeks powerful opponents"],"motivations":["Experience intense combat","Fully express his power"],"personality":["Battle-hungry","Chaotic","Arrogant","Destructive","Possessive"],"voiceSpeech":"","likesDislikes":["Likes battle","Likes powerful opponents","Dislikes restrained power"],"majorLifeEvents":"Raised at Ignis Peaks\nBonded with Ignis through combat\nProtected infant Ash\nDelivered Ash to Hecate''s great-aunt\nMemories altered\nDisappeared"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Ignis\nLeviathans","partner":"","children":"","siblings":"Ife\nEzra\nGaius\nRuchika\nShailara\nAsh","worldConnections":"Ignis Peaks","relationshipNotes":"Ife shares both parents with Rahim and manifests the same Fire and Water lineage as Steam rather than Blood. Rahim protected Ash as an infant and delivered Ash safely to Hecate''s great-aunt before disappearing."},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":"97d4dc51-d1bf-4f80-9e77-3955ba9dad35","workflow_status":"draft","family_record_id":"7f13ea09-709b-4aff-8d52-e65832afb12b","faction_record_id":null}','2026-09-25T17:16:40.693569+00:00');
