INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('a00a7bf5-0d3e-406c-b3cc-b5702197879b','studio_characters','231f402f-3543-4506-a286-8bd29c6974e1','Ezra','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"231f402f-3543-4506-a286-8bd29c6974e1","name":"Ezra","media":{"tbdFields":"","canonLocks":"Alias: The Sapphire Dragon\nLight caramel skin\nDruskari-African + Faelite-White heritage\nSapphire blue eyes\nBlack and silver-white hair\nSapphire blue primary palette\nLightning element\nFire + Air elemental heritage\nCrystalline dragon scales\nStorm-cloud dragon wings\nAnime visual style","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/portrait/1790356417100-ezra-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Use the established anime production-sheet design as Ezra''s primary visual reference. Human and dragon artwork should emphasize sapphire blue, stark white, silver, black, crystalline shapes, and electrical effects. His human appearance must retain his light caramel complexion and mixed Druskari-African and Faelite-White features.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/reference/1790356429322-ezra-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/alternate/1790356437345-ezra-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ezra","race":"Elemental Dragon","alias":"The Sapphire Dragon","gender":"Male","titles":"Lightning Prince","subrace":"","summary":"Ezra, known as the Sapphire Dragon, is a Lightning Dragon born from the union of primal Fire and Air. Brilliant, volatile, and exceptionally fast, he embodies the friction between heat and atmosphere. He carries himself like a high-born prince and openly considers his speed, power, and lineage proof that he is destined for greatness.","heritage":"Druskari-African + Faelite-White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Air"},"abilities":{"weapons":"","strengths":"Extreme speed\nExplosive offense\nAerial mobility\nRapid strikes\nElectrical paralysis\nPlasma attacks\nStorm manipulation","weaknesses":"Arrogance\nImpatience\nPoor defensive patience\nEasily provoked\nOverconfidence","combatStyle":["High-speed offense","Rapid-hit combat","Aerial combat","Hit-and-run attacks","Showboating","Electrical suppression"],"limitations":["Favors offense over defense","Can underestimate slower opponents"],"powerSource":["Primal Fire","Primal Air","Lightning"],"abilityNotes":"Ezra''s Lightning element results from the interaction of Fire and Air. He can manipulate electrical currents and plasma, create localized storms, electrify his claws, and generate enormous static charges. His movement can produce sonic cracks, and Lightning Shift allows brief transitions into electrical energy.","combatProfile":"Ezra fights through overwhelming speed and relentless offensive pressure. He circles opponents, attacks from rapidly changing angles, and uses electrical shocks to disrupt movement before delivering additional strikes. He prefers humiliating opponents through superior speed rather than patiently wearing them down.","weaponDetails":"","transformations":"Sapphire Dragon Form\nLightning Shift","primaryAbilities":"Lightning Manipulation\nElectrical Current Manipulation\nPlasma Manipulation\nLightning Generation\nStorm Generation","secondaryAbilities":"Extreme Speed\nElectrical Paralysis\nStatic Charge Generation\nAtmospheric Mobility\nEnergy Transformation","signatureTechniques":"Lightning Shift\nSonic Dash\nPlasma Burst\nElectrical Claws\nThunderstorm Summon","transformationDetails":"In Sapphire Dragon Form, Ezra becomes a sharp, aerodynamic dragon covered in brilliant electric-blue and stark-white crystalline scales. His anatomy favors jagged, streamlined shapes built for extreme aerial speed. Dark storm-cloud wings churn with internal lightning while electrical arcs continuously travel between his horns, spine, wings, and scales. Lightning Shift temporarily converts his body into electrical energy for near-instantaneous short-distance movement."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Athletic","Broad-shouldered"],"nails":"","eyeHex":["Sapphire Blue — #1261FF"],"height":"","makeup":"","weight":"","hairHex":["Black — #11131A","Silver-White — #E5E8F0"],"skinHex":["Light Caramel — #B98263"],"eyeColor":["Sapphire blue"],"grooming":"Immaculate","skinTone":["Light caramel"],"wardrobe":"Noble tunics\nLayered court attire\nElite champion armor\nLong coats\nArmored boots","hairColor":["Black","Silver-white"],"hairStyle":"Tousled two-tone hair","accessories":"Sapphire earrings\nDecorative chains\nSilver clasps\nArmored gauntlets","faceDetails":["Sharp jawline","Refined features","High cheekbones"],"hairTexture":["Thick","Wavy"],"colorPalette":"Sapphire Blue — #1261FF\nDeep Blue — #102B68\nMidnight Navy — #091426\nSilver — #C8CFDA\nStark White — #F4F5F7\nBlack — #11131A","dominantHand":"","outfitColors":"Sapphire blue\nDeep blue\nStark white\nSilver\nBlack","alternateForm":["Sapphire Dragon"],"clothingStyle":"Flashy high-born clothing inspired by early European court fashion and elite medieval champions. Ezra favors structured silhouettes, sweeping layers, luxurious detailing, and clothing designed to make his status immediately apparent.","appearanceNotes":"Ezra''s human design reflects his mixed Druskari-African and Faelite-White heritage. His light caramel complexion contrasts strongly with his sapphire, silver, white, and black palette. His overall appearance should remain handsome, sharp, aristocratic, and unmistakably confident.","outfitMaterials":["Fine woven fabric","Leather","Polished metal"],"postureMovement":["Confident","Regal","Quick","Explosive"],"signatureOutfit":"A high-born layered court ensemble combining sweeping noble tunics with fitted champion armor. Deep sapphire fabrics, stark white layers, silver detailing, structured shoulders, fitted gloves, and armored boots create a sharp princely silhouette.","distinguishingFeatures":["Split black and silver-white hair","Piercing gaze"]},"created_at":"2026-09-25T16:43:35.075732+00:00","updated_at":"2026-09-25T17:14:43.75119+00:00","is_complete":true,"origin_lore":{"fears":["Being overshadowed","Being proven inferior"],"goals":["Become the dominant heir","Earn unmatched recognition"],"beliefs":["Speed determines victory","Power deserves recognition","He is the rightful heir"],"culture":"","lineage":"Primal Fire Dragon + Primal Air Dragon","storyArc":"Ezra begins convinced that his speed, lineage, and spectacular power place him above his siblings. His rivalries increasingly confront him with abilities that cannot simply be overwhelmed by moving faster, forcing his certainty about superiority to be challenged.","backstory":"Ezra was born from the elemental union of Ignis and Atherous. Fire supplied the heat and raw energy of his nature, while Air supplied atmospheric movement and extraordinary speed. Their combination manifested in Ezra as Lightning, producing one of the family''s fastest and most visually explosive elemental descendants.","childhood":"","lifestyle":["Competitive","High-energy","Luxury-loving"],"storyRole":"Ezra serves as the brilliant family rival whose immense talent is complicated by pride and ambition. His competitive nature creates friction with siblings whose abilities challenge his belief that speed and overwhelming offense make him superior.","birthplace":"","psychology":["Massive ego","Craves recognition","Obsessed with superiority","Competitive with family","Equates speed with dominance"],"motivations":["Prove his superiority","Surpass his siblings","Claim personal glory","Honor his lineage"],"personality":["Arrogant","Loud","Proud","Competitive","Confident","Flashy","Ambitious","Easily insulted","Attention-seeking"],"voiceSpeech":["Confident","Boastful","Sharp","Provocative"],"likesDislikes":["Glory","Praise","Admiration","Speed","Competition","Luxury","Being underestimated","Losing","Slowness","Being ignored"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/portrait/1790356417100-ezra-character-portrait.png","relationships":{"allies":"","rivals":"Ife","enemies":"","mentors":"","parents":"Ignis\nAtherous","partner":"","children":"","siblings":"Ife\nRahim\nGaius\nAsh","worldConnections":"","relationshipNotes":"Ezra constantly provokes Ife and is frustrated by the durability of her defensive abilities. He respects Rahim''s raw power but dislikes his chaotic brutality. He considers Gaius boring and overly quiet despite their shared connection through Atherous. Ezra treats Ash with cold disdain because of Ash''s mortal maternal lineage and views him as a blemish on Ignis''s bloodline, unaware of how dangerous Ash''s smothering magic could be to his electricity."},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":null,"workflow_status":"draft","family_record_id":"a040ba80-3b84-4caf-b268-f0d59e8cbd2e","faction_record_id":null}','2026-09-25T17:19:34.130771+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('9fd43533-226e-41a6-b7f0-305182be289c','studio_characters','231f402f-3543-4506-a286-8bd29c6974e1','Ezra','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"231f402f-3543-4506-a286-8bd29c6974e1","name":"Ezra","media":{"tbdFields":"","canonLocks":"Alias: The Sapphire Dragon\nLight caramel skin\nDruskari-African + Faelite-White heritage\nSapphire blue eyes\nBlack and silver-white hair\nSapphire blue primary palette\nLightning element\nFire + Air elemental heritage\nCrystalline dragon scales\nStorm-cloud dragon wings\nAnime visual style","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/portrait/1790356417100-ezra-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Use the established anime production-sheet design as Ezra''s primary visual reference. Human and dragon artwork should emphasize sapphire blue, stark white, silver, black, crystalline shapes, and electrical effects. His human appearance must retain his light caramel complexion and mixed Druskari-African and Faelite-White features.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/reference/1790356429322-ezra-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/alternate/1790356437345-ezra-alternate-true-form.png"},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ezra","race":"Elemental Dragon","alias":"The Sapphire Dragon","gender":"Male","titles":"Lightning Prince","subrace":"","summary":"Ezra, known as the Sapphire Dragon, is a Lightning Dragon born from the union of primal Fire and Air. Brilliant, volatile, and exceptionally fast, he embodies the friction between heat and atmosphere. He carries himself like a high-born prince and openly considers his speed, power, and lineage proof that he is destined for greatness.","heritage":"Druskari-African + Faelite-White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Air"},"abilities":{"weapons":"","strengths":"Extreme speed\nExplosive offense\nAerial mobility\nRapid strikes\nElectrical paralysis\nPlasma attacks\nStorm manipulation","weaknesses":"Arrogance\nImpatience\nPoor defensive patience\nEasily provoked\nOverconfidence","combatStyle":["High-speed offense","Rapid-hit combat","Aerial combat","Hit-and-run attacks","Showboating","Electrical suppression"],"limitations":["Favors offense over defense","Can underestimate slower opponents"],"powerSource":["Primal Fire","Primal Air","Lightning"],"abilityNotes":"Ezra''s Lightning element results from the interaction of Fire and Air. He can manipulate electrical currents and plasma, create localized storms, electrify his claws, and generate enormous static charges. His movement can produce sonic cracks, and Lightning Shift allows brief transitions into electrical energy.","combatProfile":"Ezra fights through overwhelming speed and relentless offensive pressure. He circles opponents, attacks from rapidly changing angles, and uses electrical shocks to disrupt movement before delivering additional strikes. He prefers humiliating opponents through superior speed rather than patiently wearing them down.","weaponDetails":"","transformations":"Sapphire Dragon Form\nLightning Shift","primaryAbilities":"Lightning Manipulation\nElectrical Current Manipulation\nPlasma Manipulation\nLightning Generation\nStorm Generation","secondaryAbilities":"Extreme Speed\nElectrical Paralysis\nStatic Charge Generation\nAtmospheric Mobility\nEnergy Transformation","signatureTechniques":"Lightning Shift\nSonic Dash\nPlasma Burst\nElectrical Claws\nThunderstorm Summon","transformationDetails":"In Sapphire Dragon Form, Ezra becomes a sharp, aerodynamic dragon covered in brilliant electric-blue and stark-white crystalline scales. His anatomy favors jagged, streamlined shapes built for extreme aerial speed. Dark storm-cloud wings churn with internal lightning while electrical arcs continuously travel between his horns, spine, wings, and scales. Lightning Shift temporarily converts his body into electrical energy for near-instantaneous short-distance movement."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Athletic","Broad-shouldered"],"nails":"","eyeHex":["Sapphire Blue — #1261FF"],"height":"","makeup":"","weight":"","hairHex":["Black — #11131A","Silver-White — #E5E8F0"],"skinHex":["Light Caramel — #B98263"],"eyeColor":["Sapphire blue"],"grooming":"Immaculate","skinTone":["Light caramel"],"wardrobe":"Noble tunics\nLayered court attire\nElite champion armor\nLong coats\nArmored boots","hairColor":["Black","Silver-white"],"hairStyle":"Tousled two-tone hair","accessories":"Sapphire earrings\nDecorative chains\nSilver clasps\nArmored gauntlets","faceDetails":["Sharp jawline","Refined features","High cheekbones"],"hairTexture":["Thick","Wavy"],"colorPalette":"Sapphire Blue — #1261FF\nDeep Blue — #102B68\nMidnight Navy — #091426\nSilver — #C8CFDA\nStark White — #F4F5F7\nBlack — #11131A","dominantHand":"","outfitColors":"Sapphire blue\nDeep blue\nStark white\nSilver\nBlack","alternateForm":["Sapphire Dragon"],"clothingStyle":"Flashy high-born clothing inspired by early European court fashion and elite medieval champions. Ezra favors structured silhouettes, sweeping layers, luxurious detailing, and clothing designed to make his status immediately apparent.","appearanceNotes":"Ezra''s human design reflects his mixed Druskari-African and Faelite-White heritage. His light caramel complexion contrasts strongly with his sapphire, silver, white, and black palette. His overall appearance should remain handsome, sharp, aristocratic, and unmistakably confident.","outfitMaterials":["Fine woven fabric","Leather","Polished metal"],"postureMovement":["Confident","Regal","Quick","Explosive"],"signatureOutfit":"A high-born layered court ensemble combining sweeping noble tunics with fitted champion armor. Deep sapphire fabrics, stark white layers, silver detailing, structured shoulders, fitted gloves, and armored boots create a sharp princely silhouette.","distinguishingFeatures":["Split black and silver-white hair","Piercing gaze"]},"created_at":"2026-09-25T16:43:35.075732+00:00","updated_at":"2026-09-25T17:19:34.130771+00:00","is_complete":false,"origin_lore":{"fears":["Being overshadowed","Being proven inferior"],"goals":["Become the dominant heir","Earn unmatched recognition"],"beliefs":["Speed determines victory","Power deserves recognition","He is the rightful heir"],"culture":"","lineage":"Primal Fire Dragon + Primal Air Dragon","storyArc":"Ezra begins convinced that his speed, lineage, and spectacular power place him above his siblings. His rivalries increasingly confront him with abilities that cannot simply be overwhelmed by moving faster, forcing his certainty about superiority to be challenged.","backstory":"Ezra was born from the elemental union of Ignis and Atherous. Fire supplied the heat and raw energy of his nature, while Air supplied atmospheric movement and extraordinary speed. Their combination manifested in Ezra as Lightning, producing one of the family''s fastest and most visually explosive elemental descendants.","childhood":"","lifestyle":["Competitive","High-energy","Luxury-loving"],"storyRole":"Ezra serves as the brilliant family rival whose immense talent is complicated by pride and ambition. His competitive nature creates friction with siblings whose abilities challenge his belief that speed and overwhelming offense make him superior.","birthplace":"","psychology":["Massive ego","Craves recognition","Obsessed with superiority","Competitive with family","Equates speed with dominance"],"motivations":["Prove his superiority","Surpass his siblings","Claim personal glory","Honor his lineage"],"personality":["Arrogant","Loud","Proud","Competitive","Confident","Flashy","Ambitious","Easily insulted","Attention-seeking"],"voiceSpeech":["Confident","Boastful","Sharp","Provocative"],"likesDislikes":["Glory","Praise","Admiration","Speed","Competition","Luxury","Being underestimated","Losing","Slowness","Being ignored"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/portrait/1790356417100-ezra-character-portrait.png","relationships":{"allies":"","rivals":"Ife","enemies":"","mentors":"","parents":"Ignis\nAtherous","partner":"","children":"","siblings":"Ife\nRahim\nGaius\nAsh","worldConnections":"","relationshipNotes":"Ezra constantly provokes Ife and is frustrated by the durability of her defensive abilities. He respects Rahim''s raw power but dislikes his chaotic brutality. He considers Gaius boring and overly quiet despite their shared connection through Atherous. Ezra treats Ash with cold disdain because of Ash''s mortal maternal lineage and views him as a blemish on Ignis''s bloodline, unaware of how dangerous Ash''s smothering magic could be to his electricity."},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":null,"workflow_status":"draft","family_record_id":"a040ba80-3b84-4caf-b268-f0d59e8cbd2e","faction_record_id":null}','2026-09-25T17:19:36.407623+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('7494f75e-cdcc-4496-bb59-7b650e7e7836','studio_characters','bc34fdb8-22a5-439b-8067-e5b670626b0f','Shailara','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"bc34fdb8-22a5-439b-8067-e5b670626b0f","name":"Shailara","media":{"tbdFields":"Birth date\nAge\nHeight\nWeight\nBirthplace\nCurrent residence\nOccupation\nMother''s name","canonLocks":"Warm bronze-brown skin\nJade green eyes\nDark brown hair\nEmerald hair undertones\nPointed Sylvani ears\nLiving vines in hair\nNatural flowers in hair\nForest-green signature outfit\nEmerald crystal motifs\nLiving stone dragon form","galleryUrl":"","mediaNotes":"Established visual references include Shailara''s human portrait, Earth Dragon form, and full visual production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/portrait/1790356221787-shailara-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Preserve the established human and dragon designs. Her visual identity should consistently combine stone, emerald crystal, living vegetation, refined Sylvani elements, and Sunspear Indian heritage.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/reference/1790356235758-shailara-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/alternate/1790356241924-shailara-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Shailara","race":"Half Earth Dragon / Half Sylvani Elf","alias":"The Living Mountain","gender":"Female","titles":"The Living Mountain\nKeeper of the Emerald Vein","subrace":"","summary":"Shailara is the daughter of Terrax, an Earth Dragon of Sunspear Indian heritage, and a Sylvani Elf deeply connected to nature and traditional arcane magic. Known as the Living Mountain, she embodies a rare union of ancient stone and living nature. Her earth-dragon power manifests through the Emerald Vein, allowing stone, crystal, roots, and vegetation to exist as parts of the same living system.","heritage":"Indian + Sylvani Elf","homeland":"","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"Stone Blossom","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Earth + Sylvani"},"abilities":{"weapons":"","strengths":"Earth manipulation\nEnvironmental restoration\nDefensive durability\nTerrain control\nNature synergy","weaknesses":"","combatStyle":["Terrain control","Defensive combat","Environmental manipulation"],"limitations":"","powerSource":["Earth Dragon heritage","Sylvani magic","Emerald Vein"],"abilityNotes":"The Emerald Vein unifies Shailara''s earth and Sylvani inheritances, allowing stone and plant life to function together. Her Lithobloom Core causes vegetation to grow naturally from her draconic body and allows her presence to encourage ecological renewal.","combatProfile":"Shailara reshapes the battlefield through stone, roots, crystals, and rapidly growing vegetation. Her fighting style emphasizes environmental control and defense rather than reckless aggression. In dragon form, her immense stone body provides exceptional physical durability.","weaponDetails":"","transformations":"Earth Dragon Form","primaryAbilities":"Stone Manipulation\nCrystal Manipulation\nPlant Manipulation\nRoot Manipulation\nLand Restoration","secondaryAbilities":"Accelerated Plant Growth\nCrystal Growth\nLiving Stone Creation\nEcosystem Restoration\nStone-to-Wood Transmutation","signatureTechniques":"Emerald Vein\nLithobloom Core","transformationDetails":"Shailara transforms into a colossal Earth Dragon resembling a living mountain. Her body is covered in layered stone scales with moss, vines, flowers, and emerald crystal formations growing naturally across her frame. Her wings resemble interlocking petrified leaves, stone structures, and crystal branches."},"is_public":false,"appearance":{"build":["Tall","Graceful","Curvaceous"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Jade green"],"grooming":"","skinTone":["Warm bronze-brown"],"wardrobe":"Sylvani gowns\nNature-inspired ceremonial attire","hairColor":["Dark brown","Emerald undertones"],"hairStyle":"Long and flowing","accessories":"Emerald forehead jewel\nEmerald earrings\nGold jewelry\nLiving floral ornaments","faceDetails":["Elegant features","High cheekbones","Pointed ears"],"hairTexture":["Thick","Wavy"],"colorPalette":"Granite Grey\nMoss Green\nJade\nEmerald\nOlive\nEarth Brown\nSoft Gold\nIvory\nBlossom Pink","dominantHand":"","outfitColors":"Forest green\nEmerald\nIvory\nSoft gold","alternateForm":["Earth Dragon Form"],"clothingStyle":"Elegant Sylvani clothing blending natural materials, botanical motifs, flowing fabrics, gemstones, and refined ornamentation.","appearanceNotes":"Her human form visibly blends Sunspear Indian and Sylvani features. Living vegetation naturally grows among her hair and clothing. Her dragon form resembles a living mountain composed of layered stone scales, vegetation, vines, flowers, and emerald crystal growths.","outfitMaterials":["Layered fabric","Living vines","Gold ornamentation","Emerald gemstones"],"postureMovement":["Graceful","Composed"],"signatureOutfit":"An elegant forest-green Sylvani gown with botanical detailing, soft flowing ivory fabric, gold ornamentation, emerald accents, and living vines woven naturally through the design.","distinguishingFeatures":["Living vines in hair","Natural flowers in hair","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:49:43.887688+00:00","updated_at":"2026-09-25T17:13:18.46252+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Life can return","Stone can nurture growth"],"culture":["Sunspear","Sylvani"],"lineage":"Terrax + Sylvani Elf","storyArc":"","backstory":"Born from an Earth Dragon and a Sylvani Elf, Shailara inherited Terrax''s connection to stone alongside her mother''s affinity for nature and traditional arcane magic. These inheritances developed together rather than remaining separate, producing her unusual bond with living stone.","childhood":"","lifestyle":["Nature-oriented"],"storyRole":"","birthplace":"","psychology":["Values renewal","Protective of nature","Emotionally grounded"],"motivations":["Protect living ecosystems","Restore damaged land","Preserve natural balance"],"personality":["Calm","Nurturing","Patient","Compassionate","Protective","Hopeful"],"voiceSpeech":["Calm","Measured","Gentle"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/portrait/1790356221787-shailara-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Terrax","partner":"","children":"","siblings":"Nysera","worldConnections":"","relationshipNotes":"Shailara and Nysera share the same Sylvani mother but have different fathers. Nysera is a full Sylvani Elf and is intensely devoted to Shailara."},"spoiler_level":"private","race_record_id":"41d87f15-5819-4dbb-a9db-7abbdc65e92b","realm_record_id":null,"workflow_status":"draft","family_record_id":"e0563851-b12b-4a90-827f-5c38b92a4a58","faction_record_id":null}','2026-09-25T17:19:55.88144+00:00');
