INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('e508ede5-5e34-4e5e-9696-6534da722b88','studio_characters','f1a92df4-a271-4f90-beb5-662c725b2661','Mvula','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"f1a92df4-a271-4f90-beb5-662c725b2661","name":"Mvula","media":{"tbdFields":"Birth date\nExact age at death\nPronunciation\nName meaning\nHeight\nDominant hand\nParents\nSiblings\nChildhood\nExact appearance before death","canonLocks":"Male spirit\nFormer Stone Mountains scout\nOriginates from Kwaye-Zulu\nDied in a mountain crevice\nDenied final rites\nBecame a Ghede-Baka\nForcibly bound by Xolani\nTethered to Xolani''s Dead Eye\nCharcoal shadow manifestation\nWhite spirit-light eyes\nElongated spectral limbs\nFears being forgotten\nProtects Xolani reluctantly","galleryUrl":"","mediaNotes":"Use Mvula''s established portrait and full-body artwork as visual continuity references. Future artwork should preserve his charcoal-and-ash palette, spectral white eyes, gaunt silhouette, elongated fingers, smoky manifestation, and visual connection to Xolani''s Dead Eye.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/f1a92df4-a271-4f90-beb5-662c725b2661/portrait/1790321436461-mvula-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Needed\nAlternate / True Form — Needed\nFull-Body Front — Done\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Needed\nEye Reference — Needed\nOutfit Breakdown — Needed\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Mvula must remain visually connected to the established Xolani design without resembling Xolani himself. Preserve his emaciated charcoal spirit body, ash-grey fractures, white spirit-light eyes, elongated limbs, smoke-like edges, and remnants of practical Stone Mountains scout clothing. His design should communicate that he was once human before becoming a corrupted restless spirit.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/f1a92df4-a271-4f90-beb5-662c725b2661/reference/1790321444313-mvula-reference-production-sheet.png","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD","era":"500–1300 AD-inspired fantasy","name":"Mvula","race":"Restless Spirit","alias":"","gender":"Male","titles":"The Forgotten Scout\nThe Shadow of the Crevice\nThe Hunger Behind the Dead Eye","subrace":"Ghede-Baka","summary":"Mvula was once a scout of the Stone Mountains who died alone in a mountain crevice without receiving his final rites. Forgotten by the living, his abandoned spirit became a corrupted Ghede-Baka. During the Great Drought, Xolani forcibly bound Mvula through the Binding Cadence, creating a parasitic spiritual connection that ultimately tethered Mvula to Xolani''s Dead Eye.","heritage":"Kwaye-Zulu","homeland":"Stone Mountains","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Former scout","affiliation":"Xolani","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Spirit-bound to Xolani","elementalHeritage":""},"abilities":{"weapons":"Spectral influence","strengths":"Spirit perception\nPsychological warfare\nSensory manipulation\nSpectral movement\nDefensive instinct\nIntimidation","weaknesses":"Sacred salt\nFlorida Water\nConsecrated ground\nRitual cleansing","combatStyle":["Psychological warfare","Spiritual disruption","Fear induction","Sensory attacks","Defensive intervention"],"limitations":["Bound to Xolani","Cannot freely leave the bond","Xolani''s survival affects him","Manifestation depends on spiritual influence"],"powerSource":["Restless spirit energy","Dead Eye bond","Grey Space","Spiritual connection to Xolani"],"abilityNotes":"Mvula''s Choking Miasma creates crushing grief and hopelessness around Xolani. His Echoing Scream causes the target''s spirit to recoil from the body. Through Eye-Lock and the Direct Feed, he can expose a target to the horrifying Grey Space perceived through Xolani''s Dead Eye.","combatProfile":"Mvula fights indirectly through Xolani and the surrounding spirit space. He overwhelms enemies with despair, spiritual screams, visions, and sensory distortion while manifesting spectral limbs to influence combat. Although he frequently sabotages Xolani, his survival is tied to his host, causing him to intervene when Xolani faces lethal danger.","weaponDetails":"Mvula does not rely on a conventional physical weapon. He attacks through spiritual pressure, sensory manipulation, spectral manifestations, and his connection to Xolani''s Dead Eye and Asalato.","transformations":"Partial manifestation\nFull spirit manifestation","primaryAbilities":"Choking Miasma\nEchoing Scream\nEye-Lock\nSpectral Manifestation","secondaryAbilities":"Sensory manipulation\nSpectral guidance\nMotor interference\nDeath visions\nSpirit perception","signatureTechniques":"Direct Feed\nSpectral Intervention\nRhythm Sabotage","transformationDetails":"Mvula usually exists as a shadow clinging to Xolani''s back or within the Dead Eye. When his influence intensifies, more of his emaciated charcoal form emerges through smoke and ash. His elongated arms can manifest around Xolani and mimic or interfere with his movements."},"is_public":false,"appearance":{"build":["Emaciated","Elongated","Gaunt"],"nails":["Dark elongated nails"],"eyeHex":["#E9E8DF"],"height":"TBD","makeup":"","weight":"Weightless spirit","hairHex":["#11100F"],"skinHex":["#171615","#494642"],"eyeColor":["White spirit-light"],"grooming":"Spirit manifestation","skinTone":["Charcoal black","Ash grey"],"wardrobe":"Tattered scout clothing\nWeathered wraps\nShredded outer layers","hairColor":["Charcoal black"],"hairStyle":"Flowing shadow and drifting ash","accessories":"","faceDetails":["Hollow facial structure","Sunken cheeks","Gaunt jawline","Shadowed features"],"hairTexture":["Smoke-like","Shadow-like"],"colorPalette":"Charcoal black\nAsh grey\nBone white\nSmoke grey\nMoonlit silver","dominantHand":"TBD","outfitColors":"#11100F\n#292725\n#55514C\n#B8B5AD","alternateForm":["Partial shadow manifestation","Full spirit manifestation"],"clothingStyle":"Ruined Stone Mountains scout clothing fused into his spectral body. Clothing should appear ancient, practical, torn, and partially consumed by smoke.","appearanceNotes":"Mvula should remain recognizably humanoid while clearly supernatural. His silhouette is tall, thin, and unnerving, with charcoal smoke continuously peeling from his body. His elongated spectral arm frequently manifests over Xolani''s shoulder and mirrors Xolani''s Asalato movements.","outfitMaterials":["Tattered cloth","Weathered leather","Spectral smoke","Ash"],"postureMovement":["Predatory hovering","Unnatural stillness","Smoke-like movement","Clings behind Xolani"],"signatureOutfit":"Fragments of his former scout clothing remain within his manifestation as shredded, smoke-darkened layers that dissolve into ash and shadow. His silhouette should suggest the remains of a mountain scout rather than ornate ceremonial clothing.","distinguishingFeatures":["Charcoal smoke body","White spirit-light eyes","Elongated fingers","Emaciated arms","Ash-fractured form","Smoke-shrouded face","Unstable body edges"]},"created_at":"2026-09-25T07:04:10.977435+00:00","updated_at":"2026-09-25T07:30:52.506724+00:00","is_complete":true,"origin_lore":{"fears":["Being forgotten","The Void of the Forgotten","Xolani dying","Losing his final connection to life"],"goals":["Remain remembered","Preserve his existence","Make Xolani understand his suffering"],"beliefs":["The forgotten suffer twice","Spirits should not be enslaved","Memory preserves existence"],"culture":["Kwaye-Zulu","Stone Mountains"],"lineage":"Kwaye-Zulu","storyArc":"Mvula begins consumed by hatred toward the man who enslaved him. He torments Xolani through visions, sensory manipulation, and attempts to sabotage his rhythm. Xolani''s refusal to erase Mvula''s humanity slowly changes their bond, and Mvula begins protecting the person he once wanted to destroy because Xolani has become the only living witness to who Mvula was.","backstory":"Mvula was a scout from the Stone Mountains who was left to die in a mountain crevice during a tribal war. Denied final rites and eventually forgotten, his spirit remained trapped in bitterness and grief until he became a corrupted Ghede-Baka. During the Great Drought, Xolani found Mvula and forcibly imprisoned him through the Binding Cadence to power a ritual that brought Black Rain to Kwaye-Zulu. Mvula retaliated by spiritually overwriting Xolani''s left eye, becoming permanently tethered to the Dead Eye.","childhood":"TBD","lifestyle":["Exists through Xolani''s Dead Eye","Observes the spirit world","Whispers to Xolani","Interferes with Xolani''s senses","Protects his host when threatened"],"storyRole":"Mvula is both Xolani''s tormentor and reluctant guardian. He embodies the consequences of Xolani''s forbidden ritual while giving a voice to the forgotten dead. His constant presence turns Xolani''s spiritual abilities into both a weapon and an ongoing punishment.","birthplace":"Kwaye-Zulu, Stone Mountains","psychology":["Terrified of being forgotten","Resents Xolani","Carries abandonment trauma","Emotionally dependent on Xolani","Hides concern behind hostility"],"motivations":["Avoid being forgotten","Preserve his existence","Punish Xolani","Protect his remaining connection","Have his life remembered"],"personality":["Bitter","Vindictive","Observant","Hostile","Sarcastic","Manipulative","Fearful","Protective","Lonely"],"voiceSpeech":["Distorted male whisper","Ancient tone","Bitter delivery","Sardonic speech","Low spectral voice"],"likesDislikes":["Loved the smell of rain","Notices mountain flowers","Hates being forgotten","Hates spiritual enslavement","Resents forced binding"],"majorLifeEvents":"Serves as a Stone Mountains scout\nAbandoned during tribal war\nDies alone in mountain crevice\nDenied final rites\nBecomes a Ghede-Baka\nEncountered by Xolani\nForcibly bound by Binding Cadence\nPowers the Black Rain ritual\nCreates Xolani''s Dead Eye\nBecomes tethered to Xolani\nBegins reluctantly protecting Xolani"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/f1a92df4-a271-4f90-beb5-662c725b2661/portrait/1790321436461-mvula-character-portrait.png","relationships":{"allies":"Xolani — Host, former captor, and reluctant companion","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Xolani\nKwaye-Zulu\nStone Mountains\nGrey Space\nDead Eye\nAltar of the Unburied","relationshipNotes":"Mvula initially views Xolani as his jailer after being forcibly bound during the Great Drought. He tortures Xolani through visions, whispers, sensory overlap, and rhythm sabotage, yet protects him whenever death threatens them both. Xolani''s determination to remember Mvula as a man rather than a monster gradually transforms their relationship from pure hatred into reluctant mutual recognition."},"spoiler_level":"private","race_record_id":"4b626524-5522-485d-b40f-6490debf9f06","realm_record_id":"c6c8934d-b274-44f7-a1a6-a6f8f959654b","workflow_status":"draft","family_record_id":"7fe566b0-b4c5-4bef-8c77-0ab21b2a3ff4","faction_record_id":"e2b28b7d-4073-4cf3-b937-7090a913102c"}','2026-09-25T17:22:35.039401+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('808e2b9b-c8c1-4aed-bf29-9b7690cdd17a','studio_characters','35fd725a-f7b0-45a0-acc8-61958469e015','Nysera Sylvaris','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"35fd725a-f7b0-45a0-acc8-61958469e015","name":"Nysera Sylvaris","media":{"tbdFields":"","canonLocks":"Pure Sylvani Elf\nStrong resemblance to Shailara\nAmber-brown left eye\nGlacial icy-blue right eye\nLong wild dark-brown hair\nMoss-green hair highlights\nLight bronze skin\nVine-like markings\nDark emerald marking glow\nBriarfang","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/portrait/1790356295017-nysera-sylvaris-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"Preserve Nysera''s strong facial resemblance to Shailara while maintaining her fully Sylvani identity and wilder visual language. Her heterochromia, dark wild hair, moss-green highlights, light bronze skin, and vine-like markings are essential visual identifiers.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/reference/1790356310666-nysera-sylvaris-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/alternate/1790356321872-nysera-sylvaris-2-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Nysera Sylvaris","race":"Sylvani Elf","alias":"The Wild Root","gender":"Female","titles":"The Thornheart Elf\nThe Shadow of Eldoria\nKeeper of the Hollow Groves\nBeloved Sister of Shailara, The Living Mountain","subrace":"","summary":"Nysera Sylvaris is a pure Sylvani Elf known as the Wild Root and Keeper of the Hollow Groves. Where Shailara embodies calm growth and sheltering nature, Nysera represents nature''s untamed, darker will. Her chaotic temperament and forbidden-feeling Hollow Root magic make her both a troublesome presence and a potential guardian of Eldoria.","heritage":"Sylvani","homeland":"Eldoria","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Eldoria","elementalHeritage":""},"abilities":{"weapons":"Briarfang","strengths":"Unpredictable combat\nEnvironmental control\nExceptional mobility\nImprovisation\nMagical energy draining\nAdaptive weapon use","weaknesses":"","combatStyle":["Wild","Chaotic","Improvised","Acrobatic","Feral"],"limitations":"","powerSource":["The Hollow Root","Sylvani nature magic"],"abilityNotes":"The Hollow Root governs the neglected and darker aspects of nature rather than conventional nurturing growth. Gravebloom causes black flowers to erupt from the ground and drain magical energy, with stronger opponents producing larger blooms. Thornshade Forest transforms the surrounding area into black trees, twisting roots, glowing fungi, and dark vines that obey Nysera.","combatProfile":"Nysera fights more like a feral woodland spirit than a Sylvani noble. She jumps, spins, climbs, and exploits the environment while using roots for sudden movement and unconventional attacks. Her unpredictability makes her difficult to read in battle.","weaponDetails":"Briarfang is a living weapon formed from enchanted black roots. It can transform between whip, spear, bow, and blade configurations according to Nysera''s needs and mood.","transformations":"","primaryAbilities":"Dead Forest Manipulation\nBlack Root Manipulation\nFungal Manipulation\nThorn Growth\nDecay Cycle Manipulation\nShadowed Vegetation Manipulation","secondaryAbilities":"Root Mobility\nRoot Slingshot Movement\nVegetation Command","signatureTechniques":"Gravebloom\nThornshade Forest","transformationDetails":""},"is_public":false,"appearance":{"build":"","nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Amber-brown left eye","Glacial icy-blue right eye"],"grooming":"Wild and natural","skinTone":["Light bronze"],"wardrobe":"","hairColor":["Dark brown","Near-black undertones","Moss-green highlights"],"hairStyle":"Long, wild, usually unbrushed","accessories":"","faceDetails":["Elegant jawline","High cheekbones","Graceful Sylvani features"],"hairTexture":"","colorPalette":"Dark brown\nNear-black\nMoss green\nDark emerald\nAmber-brown\nIcy blue","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"Nysera strongly resembles Shailara, sharing the same elegant facial structure and graceful Sylvani features. Outsiders sometimes mistake them for twins or assume they share the same father, which secretly delights Nysera. Her moss-green hair streaks become visible in sunlight, while her vine-like markings glow dark emerald when she channels magic.","outfitMaterials":"","postureMovement":["Restless","Energetic","Acrobatic","Feral"],"signatureOutfit":"","distinguishingFeatures":["Heterochromia","Faint vine-like markings","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:47:28.813169+00:00","updated_at":"2026-09-25T17:13:05.52667+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Decay is part of nature","Untamed nature deserves protection"],"culture":["Sylvani"],"lineage":"Pure Sylvani","storyArc":"","backstory":"Nysera inherited no Terrax blood and is entirely Sylvani. Despite this, her strong resemblance to Shailara frequently causes outsiders to assume the sisters share the same father. Her unusual connection to the darker cycles of nature distinguishes her from traditional Sylvani and leaves Eldoria''s elders divided over what she may become.","childhood":"","lifestyle":["Climbs constantly","Explores wild places","Rarely sits still"],"storyRole":"Nysera serves as Eldoria''s unpredictable troublemaker and a possible future guardian. Her connection to neglected and feared aspects of nature challenges traditional Sylvani ideas about what natural magic should be.","birthplace":"Eldoria","psychology":["Idolizes Shailara","Constantly seeks stimulation","Enjoys pushing back","Intensely loyal"],"motivations":["Protect Shailara","Defend untamed nature","Follow her own instincts"],"personality":["Hyperactive","Feisty","Stubborn","Protective","Reckless","Talented","Argumentative","Distractible"],"voiceSpeech":["Energetic","Argumentative","Blunt"],"likesDislikes":["Collecting flowers Shailara touched","Sketching Shailara","Bragging about Shailara","Dislikes insults toward Shailara","Dislikes being told no"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/35fd725a-f7b0-45a0-acc8-61958469e015/portrait/1790356295017-nysera-sylvaris-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"Shailara","worldConnections":"Eldoria","relationshipNotes":"Nysera intensely adores and idolizes Shailara. She collects flowers Shailara has touched, keeps sketches of her, constantly brags about her, and readily starts fights when someone insults her. Shailara is one of the few people capable of calming Nysera down."},"spoiler_level":"private","race_record_id":"76da8c54-5f55-4b33-b807-02e8eb74e869","realm_record_id":"291c05cb-0705-495d-95be-c6037453f9b4","workflow_status":"draft","family_record_id":"00ba4f50-602d-4833-9eae-2ce8c18297e6","faction_record_id":null}','2026-09-25T17:22:38.184706+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('b6893bcd-a279-43d6-a572-37a85c2e5eb7','studio_characters','6358b47b-ec0c-4027-b539-5334a350b2ff','Count Vex','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"6358b47b-ec0c-4027-b539-5334a350b2ff","name":"Count Vex","media":{"tbdFields":"","canonLocks":"","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6358b47b-ec0c-4027-b539-5334a350b2ff/portrait/1790355157048-count-vex-character-portrait.png","visualAssets":"","productionNotes":"","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6358b47b-ec0c-4027-b539-5334a350b2ff/reference/1790355222664-count-vex-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6358b47b-ec0c-4027-b539-5334a350b2ff/alternate/1790355291182-count-vex-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Late 30s to early 40s","era":"","name":"Count Vex","race":"","alias":"The Iron Smile","gender":"Male","titles":"Grand Inquisitor of Shadowfen","subrace":"","summary":"Count Vex is the Grand Inquisitor of Shadowfen, known as the Iron Smile. Refined, controlled, and intimidating, he carries himself like a judge who has already reached a verdict. His immaculate appearance and quiet authority make every encounter feel like a formal trial.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Grand Inquisitor","affiliation":"Shadowfen","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shadowfen","elementalHeritage":""},"abilities":{"weapons":"Ceremonial Rapier","strengths":"","weaknesses":"","combatStyle":["Dueling"],"limitations":"","powerSource":"","abilityNotes":"Mass Fear Projection creates an overwhelming sensation of judgment and guilt. Those affected describe the experience as feeling as though the world itself has decided they are guilty.","combatProfile":"Vex has the lean, athletic physique of a duelist rather than a brute. His known weapon is an ornate ceremonial rapier.","weaponDetails":"An ornate ceremonial rapier carried as part of Vex''s refined inquisitorial appearance.","transformations":"Mass Fear Projection State","primaryAbilities":"Mass Fear Projection","secondaryAbilities":"","signatureTechniques":"","transformationDetails":"When Mass Fear Projection activates, Vex''s pupils narrow into thin vertical slits and dark veins spread around his eyes."},"is_public":false,"appearance":{"build":["Lean","Athletic","Duelist-built"],"nails":"","eyeHex":"","height":"6''3\"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Pale steel gray"],"grooming":"Immaculate","skinTone":["Pale"],"wardrobe":"Military dress coats\nWhite gloves\nCrimson mantles","hairColor":["Dark silver","Platinum blond"],"hairStyle":"Perfectly slicked back","accessories":"White gloves\nShadowfen insignia","faceDetails":["Sharp aristocratic face","High cheekbones","Long nose","Narrow eyes","Cold smile"],"hairTexture":["Straight","Smooth"],"colorPalette":"Black\nSilver\nWhite\nCrimson","dominantHand":"","outfitColors":"Black\nSilver\nWhite\nCrimson","alternateForm":["Mass Fear Projection State"],"clothingStyle":"Extremely refined military formalwear with aristocratic and ceremonial details.","appearanceNotes":"Vex treats his appearance as a weapon. His clothing, hair, posture, and grooming remain meticulously controlled because he considers imperfection a weakness. During Mass Fear Projection, his pupils become thin vertical slits and dark veins spread around his eyes.","outfitMaterials":"","postureMovement":["Controlled","Elegant","Deliberate"],"signatureOutfit":"Black military dress coat with silver embroidery, white gloves, and a long crimson mantle.","distinguishingFeatures":["Perpetually unimpressed expression","Immaculate grooming"]},"created_at":"2026-09-25T16:44:05.635265+00:00","updated_at":"2026-09-25T16:55:01.168335+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Imperfection equals weakness"],"culture":"","lineage":"","storyArc":"","backstory":"","childhood":"","lifestyle":["Meticulous grooming","Strict personal presentation"],"storyRole":"Grand Inquisitor of Shadowfen.","birthplace":"","psychology":["Views imperfection as weakness","Maintains strict self-control"],"motivations":"","personality":["Cold","Refined","Controlled","Judgmental","Intimidating","Aristocratic","Unimpressed"],"voiceSpeech":["Quiet","Controlled","Formal"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6358b47b-ec0c-4027-b539-5334a350b2ff/portrait/1790355157048-count-vex-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":"74fb0163-f452-4f7e-a9ea-13c15bb960db"}','2026-09-25T17:22:39.159928+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('cc884704-dc18-40ac-aa77-14083db1002d','studio_characters','68184520-5c4b-48e9-a93b-668149340e3b','Ylva Morwenna de la Vega','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"68184520-5c4b-48e9-a93b-668149340e3b","name":"Ylva Morwenna de la Vega","media":{"tbdFields":"Reference / Production Sheet\nAlternate / True Form","canonLocks":"Age 14\n5''1\" height\nOlive-pale skin\nDeep espresso near-black hair\nSlightly wavy hair\nExplorer''s braid\nIridescent violet gaze\nTraitor''s Glyph on shoulder\nSwirling iridescent aura\nPetite wiry build\nDark witch-explorer aesthetic","galleryUrl":"","mediaNotes":"Character Portrait establishes the current visual direction.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/68184520-5c4b-48e9-a93b-668149340e3b/portrait/1790356662790-ylva-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"Preserve Ylva''s youthful anime appearance, petite wiry build, olive-pale complexion, near-black braided hair, iridescent violet gaze, Traitor''s Glyph, dark witch-explorer clothing, ritual compass, and Umbral iridescence in future artwork.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/68184520-5c4b-48e9-a93b-668149340e3b/reference/1790356671135-ylva-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/68184520-5c4b-48e9-a93b-668149340e3b/alternate/1790356679144-ylva-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"14","era":"","name":"Ylva Morwenna de la Vega","race":"Witch","alias":"The Gilded Prisoner","gender":"Female","titles":"","subrace":"","summary":"A prodigious young witch and fugitive from Whisperingdale whose obsession with forbidden magical knowledge led her to Umbral Genesis. Ylva approaches magic as an unexplored system that can be mapped, calculated, and improved. After two years imprisoned in the Whispering Spire, she escaped with two boys her age and became the strategic anchor of their group.","heritage":"Spanish","homeland":"Whisperingdale","pronouns":"She/Her","birthDate":"","nicknames":"Ylvie\nLittle Cartographer","occupation":"Witch","affiliation":"Belladonna Coven","apparentAge":"14","canonStatus":"Canon","nameMeaning":"","nationality":"Whisperingdale","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""},"abilities":{"weapons":"Ritual compass","strengths":"Exceptional intelligence\nStrategic planning\nMagical precision\nRitual optimization\nAura analysis\nThree-step spell planning","weaknesses":"Limited physical strength\nRequires preparation\nVulnerable when rushed\nPrecision-dependent casting","combatStyle":["Calculated","Ritualistic","Strategic","Predictive","Seal-based"],"limitations":["Longer cast time","Complex rituals require accuracy","Traitor''s Glyph dampens earth connection"],"powerSource":["Witchcraft","Belladonna magic","Umbral exposure","Ritualism"],"abilityNotes":"Umbral exposure permanently altered Ylva''s magical resonance. Her spells can occasionally flicker in ways that bypass conventional magical shielding. Her iridescent gaze allows her to perceive magical auras as structures or patterns that she interprets like code.","combatProfile":"Ylva avoids direct physical confrontation and instead controls encounters through preparation, positioning, seals, and calculated spell sequences. She habitually plans several magical actions ahead. Her Umbral mutation can cause spells to flicker unpredictably through conventional magical defenses, but disruption of her concentration can severely reduce her effectiveness.","weaponDetails":"Ylva uses a ritualistic compass as both a navigation instrument and magical focusing tool. It assists with geometric ritual construction, veil calculations, and precise magical positioning.","transformations":"","primaryAbilities":"Calculated Ritualism\nRitual Circle Construction\nSeal Magic\nUmbral Manipulation\nAura Perception","secondaryAbilities":"Magical Analysis\nRitual Optimization\nVeil Piercing\nMagical Cartography\nAura Reading","signatureTechniques":"The Weaver''s Math\nUmbral Flicker","transformationDetails":""},"is_public":false,"appearance":{"build":["Petite","Lean","Wiry","Agile"],"nails":"","eyeHex":"","height":"5''1\" (155 cm)","makeup":"","weight":"102 lbs (46 kg)","hairHex":"","skinHex":"","eyeColor":["Iridescent violet"],"grooming":"","skinTone":["Olive-pale"],"wardrobe":"Layered ritual clothing\nExplorer clothing\nLaced boots","hairColor":["Deep espresso","Near-black"],"hairStyle":"Practical explorer''s braid","accessories":"Ritual compass\nSpellbook\nUtility pouches\nMapping tools","faceDetails":["Youthful features","Sharp attentive gaze"],"hairTexture":["Thick","Slightly wavy"],"colorPalette":"Near-black\nDeep espresso\nIridescent violet\nUmbral purple\nAntique gold","dominantHand":"","outfitColors":"Near-black\nCharcoal\nUmbral purple\nAntique gold","alternateForm":"","clothingStyle":"A practical fusion of witchcraft and explorer aesthetics. Her clothing favors layered dark fabrics, durable boots, utility belts, ritual markings, and equipment for carrying books, mapping tools, and magical components.","appearanceNotes":"Her prolonged confinement left her naturally warm Mediterranean complexion noticeably pale. Umbral exposure causes faint iridescent flickers around her hair and aura. The Traitor''s Glyph remains permanently branded on her shoulder.","outfitMaterials":["Leather","Woven cloth","Metal"],"postureMovement":["Stiff posture","Disciplined movement","Athletic grace"],"signatureOutfit":"Dark layered witch-explorer attire combining practical travel clothing with ritual garments, belts, pouches, occult detailing, and navigation-inspired accessories.","distinguishingFeatures":["Traitor''s Glyph","Swirling iridescent aura"]},"created_at":"2026-09-25T16:41:17.011413+00:00","updated_at":"2026-09-25T17:18:06.774288+00:00","is_complete":true,"origin_lore":{"fears":["Permanent confinement","Loss of intellectual freedom"],"goals":["Decode Umbral Genesis","Understand the Between-Space","Complete her magical research"],"beliefs":["Magic can be mapped","Knowledge should be tested","Tradition requires proof","Magical limits can be surpassed"],"culture":["Belladonna Coven","Whisperingdale","Spanish seafaring heritage","Master explorer tradition"],"lineage":"Belladonna Coven and master explorer ancestry","storyArc":"Her story begins with intellectual rebellion and punishment for pursuing forbidden knowledge. Escape gives Ylva the freedom she wanted, but also forces her to confront the consequences of experimentation outside controlled conditions. Her connection to Umbral Genesis challenges her to determine whether knowledge should merely be discovered or also restrained.","backstory":"Ylva discovered the Vesper Ledger, a forbidden ancestral logbook containing coordinates connected to the Between-Space and Umbral Genesis. During a Blood Moon experiment, she pierced the veil and successfully captured Umbral energy, causing a powerful resonance throughout Whisperingdale. The experiment permanently mutated her aura. She was branded with the Traitor''s Glyph and imprisoned in the Whispering Spire for two years. At fourteen, two boys her age—one wielding voodoo power and another possessing Umbral Genesis—helped her escape, and she fled with them.","childhood":"Born to Chieftain Morwenna, Ylva showed an unusual fascination with geometry, stars, navigation, and magical structure. Rather than treating magic solely as a spiritual tradition, she approached it as an unexplored territory. By age nine, she was already correcting ancient ritual circles and improving their efficiency.","lifestyle":["Constant calculation","Magical research","Mapping","Ritual study","Strategic planning"],"storyRole":"Ylva serves as the intellectual and strategic anchor of her young fugitive group. Her knowledge of forbidden texts, ritualism, navigation, and Umbral phenomena allows her to interpret forces that her companions can wield but may not fully understand.","birthplace":"Whisperingdale","psychology":["Views magic as a system","Rejects unsupported tradition","Values intellectual freedom","Hides emotional vulnerability","Feels justified in her research"],"motivations":["Understand Umbral Genesis","Map unknown magic","Break magical limitations","Preserve intellectual freedom"],"personality":["Analytical","Calculated","Precise","Quietly defiant","Strategic","Blunt","Intellectually rebellious","Disciplined","Curious","Lonely"],"voiceSpeech":["Matter-of-fact","Precise","Blunt","Analytical"],"likesDislikes":["Ancient texts","Maps","Geometry","Stars","Magical research","Intellectual freedom","Dislikes unquestioned tradition","Dislikes confinement"],"majorLifeEvents":"Corrected ancient ritual circles\nDiscovered the Vesper Ledger\nResearched Umbral Genesis\nPierced the veil\nCaptured Umbral energy\nSuffered aura mutation\nBranded with the Traitor''s Glyph\nImprisoned in the Whispering Spire\nEscaped at age fourteen\nBecame a fugitive"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/68184520-5c4b-48e9-a93b-668149340e3b/portrait/1790356662790-ylva-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Chieftain Morwenna","partner":"","children":"","siblings":"","worldConnections":"Whisperingdale\nWhispering Spire","relationshipNotes":"Ylva and Chieftain Morwenna share a painful bond shaped by love, law, and opposing philosophies of magic. Morwenna enforced Ylva''s imprisonment but later allowed the pursuit after her escape to remain deliberately weak. The Belladonna Coven elders fear Ylva''s magical development and regard her as a potential precursor to a new magical era."},"spoiler_level":"private","race_record_id":"ec309b7f-d65a-4dca-af0b-846ed7318701","realm_record_id":"11533949-e0a1-4a62-aceb-25a09ba911da","workflow_status":"draft","family_record_id":"0fede975-a6cd-4ec3-a649-6d2ed55c1863","faction_record_id":"7747ea2c-6d4f-4ff3-b0f3-c3cbda5ecd1a"}','2026-09-25T17:22:40.668434+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('2e1caf0e-36d2-4456-8546-1e93197435de','studio_characters','7afd3c82-379f-4f9a-8907-13eef84fe662','AshóNodia','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"7afd3c82-379f-4f9a-8907-13eef84fe662","name":"AshóNodia","media":{"tbdFields":"Birth date\nBirthplace\nHeight\nWeight\nDominant hand","canonLocks":"Age appearance 15–16\nSame loc hairstyle\nWarm brown skin\nEmerald green eyes\nRectangular pupils\nBlack layered clothing\nGreen witch magic\nAsh-based draconic power\nBlack Ash Dragon form","galleryUrl":"","mediaNotes":"Existing references establish Ash''s human, pseudo-dragon, and full Ash Dragon designs.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7afd3c82-379f-4f9a-8907-13eef84fe662/portrait/1790356618371-ash-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Use the established teenage production design as the primary reference. Ash should consistently appear approximately 15–16 years old. His magic visuals should emphasize black ash and green witch energy rather than conventional fire.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7afd3c82-379f-4f9a-8907-13eef84fe662/reference/1790356625725-ash-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7afd3c82-379f-4f9a-8907-13eef84fe662/alternate/1790356635134-ash-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"15–16","era":"","name":"AshóNodia","race":"Half Human + Half Dragon","alias":"Ashle","gender":"Male","titles":"The Ash Dragon\nThe Lost Son","subrace":"Dragonkin","summary":"AshóNodia is the hidden son of Ignis and Hecate. Raised under the name Ashle by his great-aunt, he inherited an unusual expression of his father''s draconic lineage: ash rather than conventional fire. His witch heritage allows him to magically ignite and manipulate that ash. Emotionally volatile and immensely powerful, Ash struggles with abandonment, belonging, and controlling abilities he was never properly taught to use.","heritage":"Duskari + Faelite","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"Ash","occupation":"","affiliation":"Kaelen''s Crew","apparentAge":"15–16","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Witch Magic"},"abilities":{"weapons":"","strengths":"Massive raw output\nArea control\nMagic disruption\nClose-range destruction\nDraconic durability\nAsh versatility","weaknesses":"Emotional instability\nPoor power control\nHigh collateral risk","combatStyle":["Aggressive","Instinctive","Area-of-effect","Close-range","Overwhelming force"],"limitations":["Does not naturally produce conventional fire","Power intensifies with emotion","Rampages impair judgment","Requires emotional regulation"],"powerSource":["Draconic blood","Hecate''s witch lineage","Ley-line magic"],"abilityNotes":"Despite being the son of Ignis, Ash does not display conventional fire-dragon properties. His inherited fire affinity manifests as ash, the residue of fire, rather than ordinary flame. Hecate''s witchcraft allows him to ignite the ash itself, producing burning enchanted ash without turning Ash into a conventional pyromancer.\n\nAshóNodia is his true name. His great-aunt gave him the everyday name Ashle, shortened to Ash.","combatProfile":"Ash fights through overwhelming pressure rather than refined technique. He floods the battlefield with ash, controls its movement through witchcraft, and can ignite it magically when attacking. His emotional state directly affects his control, making prolonged rage increasingly dangerous to allies and surroundings.","weaponDetails":"","transformations":"Pseudo Dragon Form\nAsh Dragon Form","primaryAbilities":"Ash Manipulation\nWitch-Ignited Ash\nFumemancy\nMagic Dampening","secondaryAbilities":"Smoke Manipulation\nSoot Manipulation\nEmber Manipulation\nAsh Solidification\nLey-Line Sensitivity\nEnhanced Strength\nEnhanced Speed\nEnhanced Durability\nDraconic Senses","signatureTechniques":"Dragon''s Roar\nIncinerating Blast\nCinder Step\nVolcanic Burst\nAsh Cloud\nSilent Cinder Field","transformationDetails":"Ash''s pseudo form develops horns, black scales, claws, a tail, and increased draconic physical ability. His full dragon form becomes a massive black Ash Dragon surrounded by drifting ash and green witch energy. His draconic manifestation emphasizes ash rather than conventional flame."},"is_public":false,"appearance":{"build":["Lean","Athletic"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Emerald green"],"grooming":"","skinTone":["Warm brown"],"wardrobe":"Hooded jackets\nDark fitted shirts\nUtility trousers\nCombat boots","hairColor":["Light brown"],"hairStyle":"Layered medium-length locs with loose face-framing strands","accessories":"Green pendant\nLayered necklaces\nUtility belts\nEar piercings","faceDetails":["Youthful angular face","Defined cheekbones"],"hairTexture":["Locs"],"colorPalette":"Black\nCharcoal\nAsh gray\nEmerald green\nEarth brown","dominantHand":"","outfitColors":"Black\nCharcoal\nEmerald green","alternateForm":["Pseudo Dragon Form","Ash Dragon Form"],"clothingStyle":"Dark layered street-fantasy clothing built for movement and combat.","appearanceNotes":"Ash retains the same loc hairstyle throughout his human design. His hybrid form develops horns, claws, scales, and a tail while preserving his recognizable facial features. His dragon form is predominantly black with green witch-magic visible through portions of the scales.","outfitMaterials":["Leather","Cloth","Metal"],"postureMovement":["Watchful","Tense","Explosive"],"signatureOutfit":"Black layered street-fantasy clothing with a hooded jacket, fitted shirt, utility belts, dark trousers, and strapped combat boots.","distinguishingFeatures":["Rectangular pupils","Green magical markings"]},"created_at":"2026-09-25T16:42:50.553656+00:00","updated_at":"2026-09-25T17:18:41.611409+00:00","is_complete":true,"origin_lore":{"fears":["Losing control","Hurting his allies","Being abandoned"],"goals":["Master his ash magic","Learn the truth about his parents","Reconcile with Ignis"],"beliefs":"","culture":["Old Way of Witches"],"lineage":"Ignis and Hecate","storyArc":"Ash begins as an emotionally unstable youth who understands neither his heritage nor the nature of his unusual ash abilities. His journey gradually exposes the truth of Etaceh''s identity as Hecate, Rahim''s role in saving him, and Ignis''s belief that his son had died. His growth centers on mastering his power and discovering that his separation from his family was not abandonment.","backstory":"AshóNodia was born to Ignis and Hecate, who lived under the hidden identity Etaceh. Following Hecate''s death, Rahim was compelled by her final spell to carry the infant Ash to his great-aunt in Whisperingdale. Ignis was left believing his youngest son had been lost. Ash eventually encountered Kaelen''s crew, where his uncontrolled power made Ylva''s Tranquil Hymn essential for calming his violent magical surges.","childhood":"After Hecate''s death, Ash was carried to safety under the influence of her final protective spell and delivered to his great-aunt. She raised him as Ashle and taught him within a community that preserved Hecate''s ancient magical traditions. Ash grew up unaware that Etaceh, the mother he knew of, was actually Hecate.","lifestyle":"","storyRole":"Ash serves as Kaelen''s volatile heavy hitter and as a living bridge between the Dragon God-Primals and Hecate''s ancient witch lineage. His hidden parentage connects the crew directly to Ignis, Whisperingdale, and the lost history of Hecate.","birthplace":"","psychology":["Abandonment wounds","Difficulty regulating anger","Fear of losing control","Strong need for belonging"],"motivations":["Protect his crew","Understand his origins","Control his power","Find belonging"],"personality":["Melancholy","Watchful","Quiet","Volatile","Protective","Loyal","Hot-tempered","Isolated"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":"Birth to Ignis and Hecate\nDeath of Hecate\nRescue by Rahim\nArrival in Whisperingdale\nRaised by great-aunt\nJoined Kaelen''s crew"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7afd3c82-379f-4f9a-8907-13eef84fe662/portrait/1790356618371-ash-character-portrait.png","relationships":{"allies":"Kaelen\nYlva\nSax\nZafir","rivals":"","enemies":"","mentors":"","parents":"Ignis\nHecate","partner":"","children":"","siblings":"Rahim\nIfe\nEzra","worldConnections":"Ignis Peaks\nWhisperingdale\nUmbral Empire","relationshipNotes":"Ignis does not know what became of Ash after Hecate''s death. Hecate concealed her identity as Etaceh during her hidden life with Ignis. Rahim carried Ash to safety under Hecate''s final protective spell. Ash relies heavily on Ylva''s Tranquil Hymn when his emotional state overwhelms his control."},"spoiler_level":"private","race_record_id":"d7fecdc3-89a1-49ab-8e00-3198d310e968","realm_record_id":null,"workflow_status":"draft","family_record_id":"1a437d0b-ed4f-49d2-8f8f-30c60eef7f74","faction_record_id":"f5492e8b-d617-44b1-bce7-517c90d1da55"}','2026-09-25T17:22:41.344973+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('067ace7f-be67-4409-972c-b191220ecac5','studio_characters','7e07c96b-9f3f-495f-b7b5-1e14cc4875f4','Rahim','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"7e07c96b-9f3f-495f-b7b5-1e14cc4875f4","name":"Rahim","media":{"tbdFields":"Birth date\nAge\nHeight\nWeight\nCurrent residence\nCurrent whereabouts\nOccupation\nAffiliation","canonLocks":"Mixed Black and Asian heritage\nDeep warm-brown skin\nBlack hair\nCrimson eyes\nTall muscular build\nBlack and crimson palette\nBlood-crystal aesthetic\nObsidian-black dragon scales\nGlowing crimson dragon veins\nAnime visual style","galleryUrl":"","mediaNotes":"The Reference / Production Sheet is the primary continuity reference for future Rahim artwork. Blood Dragon and blood-crystallization references establish his alternate-form visual language.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7e07c96b-9f3f-495f-b7b5-1e14cc4875f4/portrait/1790356514399-rahim-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nBlood Crystallization Reference — Done","productionNotes":"Use the established anime production sheet as Rahim''s primary visual reference. Preserve his mixed Black and Asian facial identity, dark skin, black hair, crimson eyes, muscular build, black-and-crimson wardrobe, blood-crystal aesthetic, and established Blood Dragon design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7e07c96b-9f3f-495f-b7b5-1e14cc4875f4/reference/1790356521344-rahim-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7e07c96b-9f3f-495f-b7b5-1e14cc4875f4/alternate/1790356526948-rahim-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Rahim","race":"Elemental Dragon","alias":"The Blood Dragon","gender":"Male","titles":"Crimson Blood Dragon","subrace":"Blood Dragon","summary":"Rahim is the firstborn Blood Dragon of Ignis and Leviathans. Fire and Water manifest through him as chaotic blood magic, allowing him to manipulate life force, weaponize blood, and crystallize it into devastating constructs. Battle-hungry and arrogant, he considers many less destructive elemental powers beneath his own.","heritage":"Black + Asian","homeland":"Ignis Peaks","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Water"},"abilities":{"weapons":"Blood-crystal weapons","strengths":"Extreme destructive power\nBattlefield control\nVersatile blood constructs\nLife-force absorption\nBlood-crystal durability\nAggression amplification","weaknesses":"","combatStyle":["Aggressive","Overwhelming","Close-range combat","Battlefield domination","Construct-based combat"],"limitations":"","powerSource":["Fire","Water","Blood","Life force"],"abilityNotes":"Hemocrystal Dominion allows Rahim to condense manipulated blood into extremely hard crimson crystal for armor, weapons, spikes, and constructs. Bloodlust Amplification intensifies aggression and fighting spirit around him. Life-Force Siphon draws vitality from others, while Heart of the Battlefield allows spilled blood across a battlefield to become material for his constructs.","combatProfile":"Rahim thrives in prolonged, chaotic battles where blood and aggression are abundant. He combines direct physical combat with life-force manipulation, blood constructs, crystallized weapons, and large-scale battlefield control. His presence can intensify aggression around him, making an already violent conflict increasingly unstable.","weaponDetails":"Rahim crystallizes blood into blades, spears, shields, whips, armor, and other combat constructs. The weapons can be formed rapidly from manipulated blood and reshaped during battle.","transformations":"Blood Dragon Form\nCrimson Tyrant State","primaryAbilities":"Chaotic Blood Magic\nBlood Manipulation\nBlood Crystallization\nLife-Force Siphon\nBloodlust Amplification","secondaryAbilities":"Blood Construct Creation\nBlood-Crystal Armor\nBlood-Crystal Weaponry\nBlood-Crystal Regeneration","signatureTechniques":"Hemocrystal Dominion\nHeart of the Battlefield\nBlood Spear Storm","transformationDetails":"Rahim''s Blood Dragon Form has obsidian-black scales threaded with glowing crimson veins, scarlet eyes, blood-crystal structures, and wings formed through dark draconic tissue, blood mist, and crystal. In Crimson Tyrant State, blood crystallization spreads across his body as dense crimson armor, enlarging his horns, claws, spikes, and other natural weapons."},"is_public":false,"appearance":{"build":["Tall","Muscular","Broad-shouldered"],"nails":"","eyeHex":["Crimson — #A20D1A"],"height":"","makeup":"","weight":"","hairHex":["Black — #111014"],"skinHex":["Deep Brown — #704936"],"eyeColor":["Crimson red"],"grooming":"Clean-shaven","skinTone":["Deep warm brown"],"wardrobe":"Long black coat\nDark trousers\nCombat boots","hairColor":["Black"],"hairStyle":"Tousled medium-length hair","accessories":"Crimson pendant\nEarrings\nLayered chains\nRings","faceDetails":["Sharp jawline","High cheekbones","Strong brows"],"hairTexture":["Wavy","Thick"],"colorPalette":"Blood Crimson — #8A0712\nObsidian Black — #111014\nDeep Garnet — #5E101B\nMolten Scarlet — #D4232E","dominantHand":"","outfitColors":"Black\nCrimson\nDark red\nMetallic silver","alternateForm":["Blood Dragon Form","Crimson Tyrant State"],"clothingStyle":"Dark, regal battlewear combining draconic ornamentation with a dangerous and aristocratic silhouette.","appearanceNotes":"Rahim''s human design reflects his Black paternal and Asian maternal heritage. His established visual identity uses black, crimson, and blood-crystal accents. His dragon form is covered in obsidian-black scales threaded with glowing crimson veins and increasingly develops crystalline structures as his blood crystallization intensifies.","outfitMaterials":["Dark fabric","Leather","Metal","Blood crystal"],"postureMovement":["Confident","Predatory","Commanding"],"signatureOutfit":"Black battle attire with crimson accents, an open chest, layered dark fabrics, metallic detailing, and blood-crystal ornamentation.","distinguishingFeatures":["Dragon markings","Blood-crystal formations"]},"created_at":"2026-09-25T16:43:10.905895+00:00","updated_at":"2026-09-25T17:19:13.02049+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Power should be fully expressed"],"culture":"","lineage":"Firstborn of Ignis and Leviathans","storyArc":"Rahim''s established history connects him directly to Ash''s survival. After carrying out Hecate''s protective spell and delivering Ash to safety, he vanished under circumstances tied to altered memories, leaving his family without clear knowledge of his fate.","backstory":"Rahim is the eldest child of Ignis and Leviathans, with Fire and Water manifesting through him as Blood rather than Steam. He later carried out Hecate''s protective memory spell and delivered the infant Ash safely to Hecate''s great-aunt. Rahim subsequently vanished, leaving his whereabouts unknown and his memories altered.","childhood":"Rahim was raised at Ignis Peaks and developed a strong combat bond with Ignis.","lifestyle":"","storyRole":"Rahim is the volatile eldest sibling whose immense destructive potential contrasts sharply with the more controlled elemental expressions of his family. His disappearance and altered memories leave his current role unresolved.","birthplace":"Ignis Peaks","psychology":["Craves intense combat","Disdains weaker powers","Seeks powerful opponents"],"motivations":["Experience intense combat","Fully express his power"],"personality":["Battle-hungry","Chaotic","Arrogant","Destructive","Possessive"],"voiceSpeech":"","likesDislikes":["Likes battle","Likes powerful opponents","Dislikes restrained power"],"majorLifeEvents":"Raised at Ignis Peaks\nBonded with Ignis through combat\nProtected infant Ash\nDelivered Ash to Hecate''s great-aunt\nMemories altered\nDisappeared"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7e07c96b-9f3f-495f-b7b5-1e14cc4875f4/portrait/1790356514399-rahim-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Ignis\nLeviathans","partner":"","children":"","siblings":"Ife\nEzra\nRuchika\nAsh","worldConnections":"Ignis Peaks","relationshipNotes":"Ife shares both parents with Rahim and manifests the same Fire and Water lineage as Steam rather than Blood. Rahim protected Ash as an infant and delivered Ash safely to Hecate''s great-aunt before disappearing."},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":"97d4dc51-d1bf-4f80-9e77-3955ba9dad35","workflow_status":"draft","family_record_id":"7f13ea09-709b-4aff-8d52-e65832afb12b","faction_record_id":null}','2026-09-25T17:22:42.183073+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('bce932fb-9c12-45ea-b3d4-caf8d8d8cab1','studio_characters','bc34fdb8-22a5-439b-8067-e5b670626b0f','Shailara','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"bc34fdb8-22a5-439b-8067-e5b670626b0f","name":"Shailara","media":{"tbdFields":"Birth date\nAge\nHeight\nWeight\nBirthplace\nCurrent residence\nOccupation\nMother''s name","canonLocks":"Warm bronze-brown skin\nJade green eyes\nDark brown hair\nEmerald hair undertones\nPointed Sylvani ears\nLiving vines in hair\nNatural flowers in hair\nForest-green signature outfit\nEmerald crystal motifs\nLiving stone dragon form","galleryUrl":"","mediaNotes":"Established visual references include Shailara''s human portrait, Earth Dragon form, and full visual production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/portrait/1790356221787-shailara-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Preserve the established human and dragon designs. Her visual identity should consistently combine stone, emerald crystal, living vegetation, refined Sylvani elements, and Sunspear Indian heritage.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/reference/1790356235758-shailara-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/alternate/1790356241924-shailara-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Shailara","race":"Half Earth Dragon / Half Sylvani Elf","alias":"The Living Mountain","gender":"Female","titles":"The Living Mountain\nKeeper of the Emerald Vein","subrace":"","summary":"Shailara is the daughter of Terrax, an Earth Dragon of Sunspear Indian heritage, and a Sylvani Elf deeply connected to nature and traditional arcane magic. Known as the Living Mountain, she embodies a rare union of ancient stone and living nature. Her earth-dragon power manifests through the Emerald Vein, allowing stone, crystal, roots, and vegetation to exist as parts of the same living system.","heritage":"Indian + Sylvani Elf","homeland":"","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"Stone Blossom","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Earth + Sylvani"},"abilities":{"weapons":"","strengths":"Earth manipulation\nEnvironmental restoration\nDefensive durability\nTerrain control\nNature synergy","weaknesses":"","combatStyle":["Terrain control","Defensive combat","Environmental manipulation"],"limitations":"","powerSource":["Earth Dragon heritage","Sylvani magic","Emerald Vein"],"abilityNotes":"The Emerald Vein unifies Shailara''s earth and Sylvani inheritances, allowing stone and plant life to function together. Her Lithobloom Core causes vegetation to grow naturally from her draconic body and allows her presence to encourage ecological renewal.","combatProfile":"Shailara reshapes the battlefield through stone, roots, crystals, and rapidly growing vegetation. Her fighting style emphasizes environmental control and defense rather than reckless aggression. In dragon form, her immense stone body provides exceptional physical durability.","weaponDetails":"","transformations":"Earth Dragon Form","primaryAbilities":"Stone Manipulation\nCrystal Manipulation\nPlant Manipulation\nRoot Manipulation\nLand Restoration","secondaryAbilities":"Accelerated Plant Growth\nCrystal Growth\nLiving Stone Creation\nEcosystem Restoration\nStone-to-Wood Transmutation","signatureTechniques":"Emerald Vein\nLithobloom Core","transformationDetails":"Shailara transforms into a colossal Earth Dragon resembling a living mountain. Her body is covered in layered stone scales with moss, vines, flowers, and emerald crystal formations growing naturally across her frame. Her wings resemble interlocking petrified leaves, stone structures, and crystal branches."},"is_public":false,"appearance":{"build":["Tall","Graceful","Curvaceous"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Jade green"],"grooming":"","skinTone":["Warm bronze-brown"],"wardrobe":"Sylvani gowns\nNature-inspired ceremonial attire","hairColor":["Dark brown","Emerald undertones"],"hairStyle":"Long and flowing","accessories":"Emerald forehead jewel\nEmerald earrings\nGold jewelry\nLiving floral ornaments","faceDetails":["Elegant features","High cheekbones","Pointed ears"],"hairTexture":["Thick","Wavy"],"colorPalette":"Granite Grey\nMoss Green\nJade\nEmerald\nOlive\nEarth Brown\nSoft Gold\nIvory\nBlossom Pink","dominantHand":"","outfitColors":"Forest green\nEmerald\nIvory\nSoft gold","alternateForm":["Earth Dragon Form"],"clothingStyle":"Elegant Sylvani clothing blending natural materials, botanical motifs, flowing fabrics, gemstones, and refined ornamentation.","appearanceNotes":"Her human form visibly blends Sunspear Indian and Sylvani features. Living vegetation naturally grows among her hair and clothing. Her dragon form resembles a living mountain composed of layered stone scales, vegetation, vines, flowers, and emerald crystal growths.","outfitMaterials":["Layered fabric","Living vines","Gold ornamentation","Emerald gemstones"],"postureMovement":["Graceful","Composed"],"signatureOutfit":"An elegant forest-green Sylvani gown with botanical detailing, soft flowing ivory fabric, gold ornamentation, emerald accents, and living vines woven naturally through the design.","distinguishingFeatures":["Living vines in hair","Natural flowers in hair","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:49:43.887688+00:00","updated_at":"2026-09-25T17:21:01.087194+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Life can return","Stone can nurture growth"],"culture":["Sunspear","Sylvani"],"lineage":"Terrax + Sylvani Elf","storyArc":"","backstory":"Born from an Earth Dragon and a Sylvani Elf, Shailara inherited Terrax''s connection to stone alongside her mother''s affinity for nature and traditional arcane magic. These inheritances developed together rather than remaining separate, producing her unusual bond with living stone.","childhood":"","lifestyle":["Nature-oriented"],"storyRole":"","birthplace":"","psychology":["Values renewal","Protective of nature","Emotionally grounded"],"motivations":["Protect living ecosystems","Restore damaged land","Preserve natural balance"],"personality":["Calm","Nurturing","Patient","Compassionate","Protective","Hopeful"],"voiceSpeech":["Calm","Measured","Gentle"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/bc34fdb8-22a5-439b-8067-e5b670626b0f/portrait/1790356221787-shailara-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Terrax","partner":"","children":"","siblings":"Nysera","worldConnections":"","relationshipNotes":"Shailara and Nysera share the same Sylvani mother but have different fathers. Nysera is a full Sylvani Elf and is intensely devoted to Shailara."},"spoiler_level":"private","race_record_id":"41d87f15-5819-4dbb-a9db-7abbdc65e92b","realm_record_id":null,"workflow_status":"draft","family_record_id":"e0563851-b12b-4a90-827f-5c38b92a4a58","faction_record_id":null}','2026-09-25T17:22:43.971616+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('7ec41d33-dd8f-4aa0-8ed1-ab9fcb8805af','studio_characters','e3ed8aa4-6a04-4790-9eff-6a0c06066e35','Ife','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"e3ed8aa4-6a04-4790-9eff-6a0c06066e35","name":"Ife","media":{"tbdFields":"Birth date\nExact chronological age\nWeight\nNationality\nPartner\nChildren\nNamed non-family allies\nNamed personal enemies","canonLocks":"Deep warm-brown skin\nCosmic pink eyes\nNatural black 4C hair\nLong decorated braids\nAthletic-curvaceous build\nSteam Rose signature color\nBronze and copper accessories\nBone Dragon Whip\nPink Steam Dragon true form\nIridescent wing membranes\nSteam and bubble magic","galleryUrl":"","mediaNotes":"Maintain visual continuity across all future artwork and 3D models. Pink should remain Ife''s dominant supernatural color, supported by bronze, copper, violet, pearl, and subtle iridescent blue.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/portrait/1790355886982-ife-character-portrait-2.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nBone Dragon Whip Reference — Done\nVRoid Turnaround Reference — Done\nBlender Model Reference — Done","productionNotes":"Use the established Reference / Production Sheet as the primary visual guide. Preserve Ife''s deep warm-brown complexion, cosmic pink eyes, long decorated 4C braids, athletic-curvaceous build, pink steam-woven clothing, bronze jewelry, and pink-centered elemental effects.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/reference/1790355900799-ife-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/alternate/1790355917413-ife-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ife","race":"Dragon","alias":"The Pink Steam Dragon","gender":"Female","titles":"Daughter of Fire and Water\nProtector of the Scalding Gardens\nThe Steam-Born Guardian","subrace":"Steam Dragon","summary":"Ife is the Pink Steam Dragon, born from the union of Ignis and Leviathans. Fire and Water combine within her as Steam, giving her command over superheated vapor, pressure, condensation, and supernatural bubbles. Quiet and protective by nature, she specializes in defending others and controlling the battlefield.","heritage":"African + Asian","homeland":"Ignis Peaks","pronouns":"She/Her","birthDate":"","nicknames":"Pink Steam","occupation":"Elemental Guardian","affiliation":"Ignis Peaks","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"Love","nationality":"","spoilerLevel":"","pronunciation":"EE-feh","currentResidence":"Moltenmaw Caverns","elementalHeritage":"Fire + Water"},"abilities":{"weapons":"Bone Dragon Whip","strengths":"Battlefield control\nDefensive versatility\nThermal resistance\nPressure manipulation\nEnvironmental adaptability\nWeapon synergy\nHigh elemental output\nProtective focus","weaknesses":"Extreme cold\nMoisture-depleted environments\nOverpressure\nProtective exploitation\nEmotional pressure","combatStyle":["Defensive zoning","Battlefield control","Mid-range whip combat","Containment","Counterattacking","Circular movement"],"limitations":["Steam requires elemental balance","Bubble durability is finite","Large bubbles consume more energy","Pressure releases can endanger allies","Large-scale techniques require concentration","Dragon form increases energy consumption"],"powerSource":["Primordial elemental bloodline","Fire","Water","Steam"],"abilityNotes":"Steam is Ife''s unique elemental identity rather than separate Fire and Water spellcasting. Fire manifests primarily as heat, Water as moisture and condensation, and their equilibrium produces Steam. Her bubbles act as supernatural pressure membranes capable of defense, containment, transportation, and storing extreme heat or pressure.","combatProfile":"Ife controls space through her Bone Dragon Whip, steam fields, reinforced bubbles, and pressure attacks. She prefers to contain threats, protect allies, and punish attempts to breach her defensive perimeter. Her fighting style becomes significantly more destructive when someone under her protection is threatened.","weaponDetails":"Ruchika crafted the Bone Dragon Whip from a replica of his own tail-bone structure. Its articulated bone segments are flexible, heat-resistant, self-repairing, and attuned to Ife. She can channel superheated steam through its internal structure for binding, striking, and pressure-based attacks.","transformations":"Pink Steam Dragon\nSteam Surge\nPressure-Crowned Dragon State","primaryAbilities":"Superheated Steam Generation\nSteam Manipulation\nBubble Sorcery\nThermal Pressure Manipulation\nExtreme Thermal Resistance\nElemental Condensation","secondaryAbilities":"Steam Veil\nHeat Shimmer\nBubble Platforms\nSteam Propulsion\nPressure Detection\nCondensation Tracking\nLava Encapsulation","signatureTechniques":"Steam Lash\nScalding Bind\nPressure Spike\nSteam Whip Cyclone\nBubble Prison\nGuardian Bubble\nPinkout\nScalding Garden\nLava Bloom\nScalding Veil","transformationDetails":"Ife''s true form is a massive deep rose-pink Steam Dragon with translucent underlayers, obsidian-edged markings, cosmic pink eyes, and iridescent bubble-film wing membranes. Her transformation is concealed within rapidly expanding steam as scales, claws, tail, and wings emerge. Pressure-Crowned Dragon State is a high-output state of her true form rather than a separate transformation."},"is_public":false,"appearance":{"build":["Athletic","Curvaceous","Strong thighs","Defined shoulders","Hourglass proportions"],"nails":["Almond-shaped","Dusty rose","Deep rose accents","Pearl highlights"],"eyeHex":["Main Iris Pink — #E75C9A","Deep Iris — #8E285E","Light Iris Pink — #FF8FC5","Galaxy Violet — #9C68D7","Magical Glow — #FFD0EA","Outer Iris Ring — #6F204E","Hot-Pink Ring — #FF72B6","Pupil — #291224"],"height":"5''8\" / 173 cm","makeup":["Burnt rose blush","Deep plum eyeshadow","Rose mauve eyeshadow","Iridescent pink eyelids","Pearl-pink eye highlights","Black-plum eyeliner","Smoky burgundy lower lash","Deep berry-brown lip liner","Burnt rose lips","Bubble-pearl lip highlight"],"weight":"","hairHex":["Primary Hair — #171116","Warm Black — #24191D","Brown Highlight — #49302F","Pink Reflection — #8B405F"],"skinHex":["Deep Mahogany — #6B3B32","Warm Brown — #805044","Warm Highlight — #A96E5D","Bright Highlight — #C58B78","Shadow — #45241F","Deep Shadow — #2A1615"],"eyeColor":["Cosmic pink","Iridescent pink-violet"],"grooming":"Meticulous hair, skin, jewelry, and clothing care.","skinTone":["Deep warm brown","Reddish-mahogany undertone"],"wardrobe":"Ignis Peaks casual wear\nSunna resting attire\nCombat attire\nCeremonial attire\nSunken Dominion attire","hairColor":["Natural black"],"hairStyle":"Long decorated braids with a raised braided crown and bun.","accessories":"Bronze hoop earrings\nPink gemstone earrings\nForehead jewelry\nHead chains\nHair rings\nPink hair beads\nBronze braid cuffs\nLayered necklaces\nChoker\nUpper-arm cuffs\nBracelets\nWrist cuffs\nWaist chains\nDecorative belt\nHip chains\nAnklets\nPink gemstones","faceDetails":["Softly angular oval face","High cheekbones","Defined jawline","Full lips","Softly broad nose","Almond-shaped eyes","Thick natural eyebrows","Long dark eyelashes"],"hairTexture":["4C","Dense","Tightly coiled"],"colorPalette":"Deep Mahogany — #6B3B32\nWarm Brown — #805044\nDragon Black — #171116\nSteam Rose — #C77B91\nCosmic Pink — #E75C9A\nBubble Blush — #E5A7B8\nSteam Pearl — #F2CAD5\nPressure Rose — #87485F\nBubble Violet — #9C68D7\nBubble Blue — #82C9DF\nDragon Bronze — #9B633B\nMolten Copper — #B96E46\nSteam Gold — #D9A568\nVolcanic Black — #21191C","dominantHand":"Right","outfitColors":"Dusty Steam Pink — #C77B91\nLight Rose — #E5A7B8\nPearl Pink — #F2CAD5\nDeep Rose — #87485F\nWarm Cream — #E8D3C0\nBronze — #9B633B\nCopper — #B96E46\nGold — #D9A568\nPink Gemstone — #D9568D\nBubble Violet — #B894E8\nBubble Blue — #82C9DF","alternateForm":["Pink Steam Dragon"],"clothingStyle":"Flowing early-medieval fantasy attire influenced by African and Sahelian silhouettes. Draped fabrics, split panels, wrapped garments, metallic body jewelry, and translucent steam-woven textiles emphasize movement and bubble motifs.","appearanceNotes":"Ife''s design visually balances Fire and Water through warm skin, bronze metals, flowing fabrics, iridescence, moisture, and translucent bubble motifs. Pink is her dominant supernatural color. Her magical activity increases the visibility of steam, bubbles, iridescent markings, and heat distortion.","outfitMaterials":["Steam-woven alchemical silk","Translucent magical fibers","Bronze","Copper","Pink gemstones"],"postureMovement":["Upright","Composed","Fluid","Deliberate","Circular combat movement"],"signatureOutfit":"A wrapped pink upper garment with layered asymmetrical skirt panels, translucent steam-woven fabric, a decorated metallic belt, and bronze body jewelry.","distinguishingFeatures":["Cosmic pink irises","Long decorated braids","Pink steam aura","Iridescent power markings","Heat shimmer"]},"created_at":"2026-09-25T16:39:50.039916+00:00","updated_at":"2026-09-25T17:20:26.122493+00:00","is_complete":true,"origin_lore":{"fears":["Failing to protect loved ones","Losing family","Losing emotional control"],"goals":["Master Steam magic","Understand her dual heritage","Find answers about Rahim","Protect without controlling"],"beliefs":["Strength should protect","Opposing forces can coexist","Power requires purpose","Balance creates strength"],"culture":["Ignis Peaks","Sunken Dominion","Primordial Dragonkin"],"lineage":"Primordial Fire and Water bloodline","storyArc":"Ife''s arc explores the difference between protecting others and believing she is responsible for everything that happens to them. Rahim''s disappearance challenges her belief that sufficient strength can always keep family safe. Her eventual discovery of Ash further forces her to accept that she cannot protect someone from circumstances she never knew existed.","backstory":"Born to Ignis and Leviathans, Ife emerged as a natural equilibrium between Fire and Water. Rather than inheriting two separate elemental disciplines, their opposing forces fused within her as Steam. She grew into a protective fighter who favors containment and defense, later receiving the Bone Dragon Whip from Ruchika. Rahim''s disappearance remains an unresolved emotional wound, while the existence of Ash remains unknown to her.","childhood":"Ife grew up within Moltenmaw Caverns, where volcanic heat and lava were natural parts of everyday life. She developed a strong attachment to the Sunna and learned early that she could sleep beneath its molten surface. Her childhood training focused heavily on controlling the heat, moisture, and pressure generated by her Steam Dragon physiology.","lifestyle":["Lives in Moltenmaw Caverns","Sleeps beneath the Sunna","Maintains her braids","Maintains her weapon","Practices steam control","Trains with family","Enjoys solitude"],"storyRole":"Ife serves as an Elemental Guardian and relational bridge between multiple Primordial bloodlines. Her Fire and Water heritage places her near the center of the wider elemental family while her protective nature makes her a stabilizing presence during conflict.","birthplace":"Moltenmaw Caverns","psychology":["Protective instinct","Strong emotional restraint","Over-responsibility","Difficulty accepting protection","Need for stability"],"motivations":["Protect her family","Protect the vulnerable","Maintain balance"],"personality":["Warm","Reserved","Observant","Protective","Dependable","Patient","Practical","Family-oriented","Responsible","Quietly affectionate","Stubborn"],"voiceSpeech":["Warm medium-low voice","Measured speech","Direct wording","Dry humor","Quiet when angry"],"likesDislikes":["Likes extreme warmth","Likes hot springs","Likes steam","Likes rain on warm stone","Likes quiet mornings","Likes family gatherings","Likes routine","Likes jewelry","Likes bubbles","Likes swimming","Dislikes needless cruelty","Dislikes betrayal","Dislikes reckless endangerment","Dislikes unnecessary chaos","Dislikes bullying"],"majorLifeEvents":"Birth of the Pink Steam Dragon\nChildhood in Moltenmaw Caverns\nDiscovery of the Sunna\nMastery of Bubble Sorcery\nTraining under Ignis\nReceiving the Bone Dragon Whip\nRahim''s disappearance"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/e3ed8aa4-6a04-4790-9eff-6a0c06066e35/portrait/1790355886982-ife-character-portrait-2.png","relationships":{"allies":"","rivals":"Ezra","enemies":"","mentors":"Ignis\nLeviathans\nRuchika","parents":"Ignis\nLeviathans","partner":"","children":"","siblings":"Rahim\nRuchika\nEzra\nAsh","worldConnections":"Ignis Peaks\nMoltenmaw Caverns\nSunken Dominion\nSunna","relationshipNotes":"Ife is deeply family-oriented and often assumes a protective role around those she loves. Rahim''s disappearance remains a major emotional wound. Ruchika created her Bone Dragon Whip, while Ezra shares a competitive sibling rivalry with her. Ife does not currently know that Ash exists."},"spoiler_level":"private","race_record_id":"1ec72d01-822b-4992-9434-7772a6b4e474","realm_record_id":"97d4dc51-d1bf-4f80-9e77-3955ba9dad35","workflow_status":"draft","family_record_id":"08d087d1-5f3c-4b76-9ee9-2917fe667bf1","faction_record_id":"406ddfbf-feab-4b20-9026-bd74b716fbda"}','2026-09-25T17:22:44.588654+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('11aba18b-5d12-443e-a03a-e60c62c46b21','studio_characters','231f402f-3543-4506-a286-8bd29c6974e1','Ezra','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"231f402f-3543-4506-a286-8bd29c6974e1","name":"Ezra","media":{"tbdFields":"","canonLocks":"Alias: The Sapphire Dragon\nLight caramel skin\nDruskari-African + Faelite-White heritage\nSapphire blue eyes\nBlack and silver-white hair\nSapphire blue primary palette\nLightning element\nFire + Air elemental heritage\nCrystalline dragon scales\nStorm-cloud dragon wings\nAnime visual style","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/portrait/1790356417100-ezra-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Use the established anime production-sheet design as Ezra''s primary visual reference. Human and dragon artwork should emphasize sapphire blue, stark white, silver, black, crystalline shapes, and electrical effects. His human appearance must retain his light caramel complexion and mixed Druskari-African and Faelite-White features.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/reference/1790356429322-ezra-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/alternate/1790356437345-ezra-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ezra","race":"Elemental Dragon","alias":"The Sapphire Dragon","gender":"Male","titles":"Lightning Prince","subrace":"","summary":"Ezra, known as the Sapphire Dragon, is a Lightning Dragon born from the union of primal Fire and Air. Brilliant, volatile, and exceptionally fast, he embodies the friction between heat and atmosphere. He carries himself like a high-born prince and openly considers his speed, power, and lineage proof that he is destined for greatness.","heritage":"Druskari-African + Faelite-White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Fire + Air"},"abilities":{"weapons":"","strengths":"Extreme speed\nExplosive offense\nAerial mobility\nRapid strikes\nElectrical paralysis\nPlasma attacks\nStorm manipulation","weaknesses":"Arrogance\nImpatience\nPoor defensive patience\nEasily provoked\nOverconfidence","combatStyle":["High-speed offense","Rapid-hit combat","Aerial combat","Hit-and-run attacks","Showboating","Electrical suppression"],"limitations":["Favors offense over defense","Can underestimate slower opponents"],"powerSource":["Primal Fire","Primal Air","Lightning"],"abilityNotes":"Ezra''s Lightning element results from the interaction of Fire and Air. He can manipulate electrical currents and plasma, create localized storms, electrify his claws, and generate enormous static charges. His movement can produce sonic cracks, and Lightning Shift allows brief transitions into electrical energy.","combatProfile":"Ezra fights through overwhelming speed and relentless offensive pressure. He circles opponents, attacks from rapidly changing angles, and uses electrical shocks to disrupt movement before delivering additional strikes. He prefers humiliating opponents through superior speed rather than patiently wearing them down.","weaponDetails":"","transformations":"Sapphire Dragon Form\nLightning Shift","primaryAbilities":"Lightning Manipulation\nElectrical Current Manipulation\nPlasma Manipulation\nLightning Generation\nStorm Generation","secondaryAbilities":"Extreme Speed\nElectrical Paralysis\nStatic Charge Generation\nAtmospheric Mobility\nEnergy Transformation","signatureTechniques":"Lightning Shift\nSonic Dash\nPlasma Burst\nElectrical Claws\nThunderstorm Summon","transformationDetails":"In Sapphire Dragon Form, Ezra becomes a sharp, aerodynamic dragon covered in brilliant electric-blue and stark-white crystalline scales. His anatomy favors jagged, streamlined shapes built for extreme aerial speed. Dark storm-cloud wings churn with internal lightning while electrical arcs continuously travel between his horns, spine, wings, and scales. Lightning Shift temporarily converts his body into electrical energy for near-instantaneous short-distance movement."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Athletic","Broad-shouldered"],"nails":"","eyeHex":["Sapphire Blue — #1261FF"],"height":"","makeup":"","weight":"","hairHex":["Black — #11131A","Silver-White — #E5E8F0"],"skinHex":["Light Caramel — #B98263"],"eyeColor":["Sapphire blue"],"grooming":"Immaculate","skinTone":["Light caramel"],"wardrobe":"Noble tunics\nLayered court attire\nElite champion armor\nLong coats\nArmored boots","hairColor":["Black","Silver-white"],"hairStyle":"Tousled two-tone hair","accessories":"Sapphire earrings\nDecorative chains\nSilver clasps\nArmored gauntlets","faceDetails":["Sharp jawline","Refined features","High cheekbones"],"hairTexture":["Thick","Wavy"],"colorPalette":"Sapphire Blue — #1261FF\nDeep Blue — #102B68\nMidnight Navy — #091426\nSilver — #C8CFDA\nStark White — #F4F5F7\nBlack — #11131A","dominantHand":"","outfitColors":"Sapphire blue\nDeep blue\nStark white\nSilver\nBlack","alternateForm":["Sapphire Dragon"],"clothingStyle":"Flashy high-born clothing inspired by early European court fashion and elite medieval champions. Ezra favors structured silhouettes, sweeping layers, luxurious detailing, and clothing designed to make his status immediately apparent.","appearanceNotes":"Ezra''s human design reflects his mixed Druskari-African and Faelite-White heritage. His light caramel complexion contrasts strongly with his sapphire, silver, white, and black palette. His overall appearance should remain handsome, sharp, aristocratic, and unmistakably confident.","outfitMaterials":["Fine woven fabric","Leather","Polished metal"],"postureMovement":["Confident","Regal","Quick","Explosive"],"signatureOutfit":"A high-born layered court ensemble combining sweeping noble tunics with fitted champion armor. Deep sapphire fabrics, stark white layers, silver detailing, structured shoulders, fitted gloves, and armored boots create a sharp princely silhouette.","distinguishingFeatures":["Split black and silver-white hair","Piercing gaze"]},"created_at":"2026-09-25T16:43:35.075732+00:00","updated_at":"2026-09-25T17:19:36.407623+00:00","is_complete":true,"origin_lore":{"fears":["Being overshadowed","Being proven inferior"],"goals":["Become the dominant heir","Earn unmatched recognition"],"beliefs":["Speed determines victory","Power deserves recognition","He is the rightful heir"],"culture":"","lineage":"Primal Fire Dragon + Primal Air Dragon","storyArc":"Ezra begins convinced that his speed, lineage, and spectacular power place him above his siblings. His rivalries increasingly confront him with abilities that cannot simply be overwhelmed by moving faster, forcing his certainty about superiority to be challenged.","backstory":"Ezra was born from the elemental union of Ignis and Atherous. Fire supplied the heat and raw energy of his nature, while Air supplied atmospheric movement and extraordinary speed. Their combination manifested in Ezra as Lightning, producing one of the family''s fastest and most visually explosive elemental descendants.","childhood":"","lifestyle":["Competitive","High-energy","Luxury-loving"],"storyRole":"Ezra serves as the brilliant family rival whose immense talent is complicated by pride and ambition. His competitive nature creates friction with siblings whose abilities challenge his belief that speed and overwhelming offense make him superior.","birthplace":"","psychology":["Massive ego","Craves recognition","Obsessed with superiority","Competitive with family","Equates speed with dominance"],"motivations":["Prove his superiority","Surpass his siblings","Claim personal glory","Honor his lineage"],"personality":["Arrogant","Loud","Proud","Competitive","Confident","Flashy","Ambitious","Easily insulted","Attention-seeking"],"voiceSpeech":["Confident","Boastful","Sharp","Provocative"],"likesDislikes":["Glory","Praise","Admiration","Speed","Competition","Luxury","Being underestimated","Losing","Slowness","Being ignored"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/231f402f-3543-4506-a286-8bd29c6974e1/portrait/1790356417100-ezra-character-portrait.png","relationships":{"allies":"","rivals":"Ife","enemies":"","mentors":"","parents":"Ignis\nAtherous","partner":"","children":"","siblings":"Ife\nRahim\nGaius\nAsh","worldConnections":"","relationshipNotes":"Ezra constantly provokes Ife and is frustrated by the durability of her defensive abilities. He respects Rahim''s raw power but dislikes his chaotic brutality. He considers Gaius boring and overly quiet despite their shared connection through Atherous. Ezra treats Ash with cold disdain because of Ash''s mortal maternal lineage and views him as a blemish on Ignis''s bloodline, unaware of how dangerous Ash''s smothering magic could be to his electricity."},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":null,"workflow_status":"draft","family_record_id":"a040ba80-3b84-4caf-b268-f0d59e8cbd2e","faction_record_id":null}','2026-09-25T17:22:45.432239+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('b41a0d28-e25e-485c-b1d5-cc10d5e78ecd','studio_characters','6d00acef-a778-40bb-bfdc-f72787d0168f','Zafir','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"6d00acef-a778-40bb-bfdc-f72787d0168f","name":"Zafir","media":{"tbdFields":"Birth date\nExact age\nWeight\nDominant hand\nMother''s name\nFather''s name","canonLocks":"Warm bronze skin\nGolden amber eyes\nMint-blue hair\nGlowing blue Genie markings\n5''4\" height\nLean athletic build\nSunspear attire\nTeal and gold palette\nSapphire jewelry\nPersistent hovering","galleryUrl":"","mediaNotes":"The Reference / Production Sheet is the primary visual reference for future Zafir artwork.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done","productionNotes":"Preserve Zafir''s warm bronze skin, mint-blue hair, golden amber eyes, glowing blue Genie markings, short lean build, and ornate Sunspear clothing. He should usually appear hovering rather than standing normally. Magic manifests through cerulean or mint-blue light, mist, and silver highlights.","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Zafir","race":"Half-Genie / Half-Human","alias":"The Infinite Conjurer","gender":"Male","titles":"Wild Card","subrace":"Half-Genie","summary":"Zafir is a Half-Genie and Half-Human Sunspear whose impossible birth was made possible by his mother''s Great Wish. His father''s entire Genie essence was woven into Zafir''s soul to sustain his existence. Charismatic, theatrical, and effortlessly confident, Zafir travels with Kaelen''s crew while searching for the Lamp of the First Djinn and a way to separate his father''s essence from his own.","heritage":"Sunspear","homeland":"Shifting Sands","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Conjurer","affiliation":"Kaelen''s Crew","apparentAge":"Early 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Extreme magical versatility\nAerial mobility\nMatter alteration\nPhysical evasion\nTangible conjuration\nDesert navigation\nSocial manipulation","weaknesses":"Severe post-wish exhaustion\nVulnerability after granting wishes","combatStyle":["Aerial combat","Sunspear combat","Reality manipulation","Transmutation","Conjured weapons","Evasive combat"],"limitations":["One wish per person per lifetime","Cannot grant his own wishes","Wish granting drains Chronoessence"],"powerSource":["Genie essence","Internal Chronoessence"],"abilityNotes":"Zafir''s magic is internal rather than drawn from an external Chronoessence source. His conjurations emerge through mint-blue mist accompanied by the scent of jasmine and ozone. His One-Wish Rule allows him to grant one wish to each person during that person''s lifetime, but fulfilling a wish severely depletes his Chronoessence and can leave him vulnerable for several days.","combatProfile":"Zafir fights from the air whenever possible, using mobility and unpredictability rather than remaining in direct exchanges. He alters matter, creates tangible phantasms, and shifts into mist to evade attacks. His Sunspear training gives him a grounded combat foundation when magic is unavailable.","weaponDetails":"","transformations":"Mist Form\nMiniature Form\nShapeshifted Forms","primaryAbilities":"Conjuration\nTransmutation\nMaterial Manipulation\nPhantasm Creation\nIntangibility\nFlight","secondaryAbilities":"Shapeshifting\nMiniaturization\nMist Transformation\nDesert Hazard Sensing\nTemporal Dust Detection","signatureTechniques":"One-Wish Rule\nHard-Light Conjuration\nMist Form\nMiniature Form","transformationDetails":"Zafir can dissolve his physical body into a gaseous mist capable of bypassing barriers and physical attacks. He can also transmute himself into animals, other people, or a miniature version of himself while retaining his personality and magical nature."},"is_public":false,"appearance":{"build":["Short","Lean","Athletic"],"nails":"","eyeHex":"","height":"5''4\"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Golden amber"],"grooming":"Well-groomed","skinTone":["Warm bronze"],"wardrobe":"Sleeveless embroidered vests\nHarem pants\nRoyal Sunspear silks\nFlowing waist fabrics","hairColor":["Mint-blue"],"hairStyle":"Voluminous gravity-defying waves","accessories":"Gold bangles\nJeweled waist-cinch\nSapphire earring\nGold necklace","faceDetails":["Sharp features","Handsome face","Almond-shaped eyes"],"hairTexture":["Thick"],"colorPalette":"Mint Blue\nCerulean\nSilver\nTeal\nGold\nWarm Bronze","dominantHand":"","outfitColors":"Teal\nGold\nBlack\nWhite","alternateForm":["Mist Form","Miniature Form"],"clothingStyle":"Opulent Sunspear clothing designed for unrestricted movement and aerial poses. Open-chested garments deliberately leave his Genie markings visible.","appearanceNotes":"Zafir''s blue markings extend from the crown of his head to the soles of his feet and pulse when he channels magic. His hair and loose fabrics subtly drift as though suspended underwater. He commonly hovers several inches above the ground, making his short stature less immediately apparent.","outfitMaterials":["Silk","Gold embroidery","Sheer fabric"],"postureMovement":["Persistent hovering","Fluid movement","Weightless movement","Relaxed floating poses"],"signatureOutfit":"A short sleeveless embroidered vest worn over a bare chest with high-waisted teal harem pants, gold jewelry, and flowing Sunspear fabrics.","distinguishingFeatures":["Glowing blue Genie markings"]},"created_at":"2026-09-25T17:24:34.742151+00:00","updated_at":"2026-09-25T17:24:34.742151+00:00","is_complete":false,"origin_lore":{"fears":["Losing his father permanently","Being exploited as an artifact","Losing his identity","Having his wishes abused"],"goals":["Find the Lamp of the First Djinn","Untangle his father''s essence","Meet his father","Understand the Shifting Sands"],"beliefs":["Wishes should carry meaning","Greed destroys people","Freedom is essential","Sacrifice gives wishes value"],"culture":["Sunspear","Navigator"],"lineage":"Sunspear","storyArc":"Zafir''s search for the Lamp of the First Djinn forces him to confront whether becoming whole requires separating himself from the father whose essence helped create him. His journey through the Shifting Sands becomes both a search for his father and an exploration of his own identity.","backstory":"Genies normally cannot reproduce with mortals. Zafir''s mother used her final Great Wish to conceive a child with the Genie she loved. The wish required Zafir''s father''s entire essence to be woven into Zafir, leaving the boy carrying both his own soul and his father''s essence. Zafir eventually began searching for the Lamp of the First Djinn in hopes of untangling them.","childhood":"Zafir was raised by his mother in a village of Master Navigators within the Shifting Sands. He learned Sunspear combat, star-mapping, desert survival, and how to read signs associated with Gaius and Ruchika. His unusual Genie traits made him both valuable to the village and a target for Desert Raiders.","lifestyle":["Prefers hovering to walking","Enjoys social settings","Explores ancient ruins","Searches magical nexuses","Avoids unnecessary physical labor"],"storyRole":"Zafir serves as the charismatic wild card of Kaelen''s crew. His reality-warping abilities provide extraordinary versatility, while his knowledge of the Shifting Sands makes him essential when the crew enters Genie territory.","birthplace":"Shifting Sands","psychology":["Feels divided between two identities","Masks insecurity with confidence","Values personal freedom","Distrusts greed","Protective of his wish magic"],"motivations":["Understand his Genie heritage","Restore his father","Protect his autonomy","Prevent misuse of wishes"],"personality":["Charismatic","Confident","Enigmatic","Romantic","Playful","Witty","Theatrical","Selective","Stylish","Detached"],"voiceSpeech":["Speaks in third person","Smooth delivery","Playful teasing","Elegant phrasing","Slightly theatrical"],"likesDislikes":["Beautiful things","Stories","Teasing Sax","Jasmine","Stargazing","Greed","Confinement","Being underestimated","Wasted wishes"],"majorLifeEvents":"Born through the Great Wish\nFather''s essence merged with his soul\nRaised among the Master Navigators\nBecame a Navigator scout\nTargeted by Desert Raiders\nJoined Kaelen''s Crew\nBegan searching for the First Djinn''s Lamp"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"Kaelen\nSax","rivals":"Sax","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Shifting Sands\nShifting Citadel\nLamp of the First Djinn","relationshipNotes":"Zafir''s unnamed Genie father sacrificed his separate existence during the Great Wish that created Zafir, leaving his essence woven into Zafir''s soul. His unnamed Sunspear mother raised him among the Navigators and taught him the story of his father''s sacrifice. Zafir shares a playful rivalry with Sax and frequently provokes him through teasing and effortless displays of magic."},"spoiler_level":"private","race_record_id":null,"realm_record_id":"48066562-cd1c-4b72-8c29-399594efad38","workflow_status":"draft","family_record_id":null,"faction_record_id":"f5492e8b-d617-44b1-bce7-517c90d1da55"}','2026-09-25T17:24:41.778519+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('30462be6-6e5b-4601-8a68-a7c9b4a6854b','studio_characters','74fd4dac-0364-45fd-9aae-2e363ac3706d','Silas','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"74fd4dac-0364-45fd-9aae-2e363ac3706d","name":"Silas","media":{"tbdFields":"Age\nWeight\nDominant hand\nBirth date\nParents'' names\nBrother''s name\nWife''s name\nDaughter''s name","canonLocks":"Human\nDeep ebony skin\nLilac eyes\nBlack 4C hair\nSubtle undercut\nFull beard\nThin connected mustache\nThick arched eyebrows\nVoodoo-style tattoos\n6''4\" height\nMuscular build\nBone adornments\nFeather adornments\nAnimal-hide clothing\nHumorous public persona\nGloomy private persona","galleryUrl":"","mediaNotes":"The smiling Silas reference represents the protective persona he commonly presents around Sax. The darker full-body reference represents the grief, fury, and psychological instability beneath that persona.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nAlternate Mood Reference — Done\nSilas and Sax Reference — Done","productionNotes":"Maintain the contrast between Silas''s public persona and his private emotional state. His familiar design should feel warm, charismatic, witty, and slightly mischievous. When the emotional mask drops, preserve the same face and design while replacing the smile with a dark blank stare, severe frown, visible rage, disorientation, and a gloomy aura.","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Silas","race":"Human","alias":"","gender":"Male","titles":"Grand Voodoo Priest","subrace":"","summary":"Silas is the Grand Voodoo Priest of Moonwood Vail and a master of ancestral magic, spiritual crossroads, and curse-weaving. Beneath his witty, carefree persona is a deeply wounded survivor whose family was slaughtered during Captain Blackheart''s pirate raid. He raises and trains his surviving nephew, Sax, while guarding the balance between the physical and spiritual realms. He later becomes a mentor to Kaelen, teaching him spiritual grounding techniques capable of stabilizing Umbral Genesis.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Grand Voodoo Priest","affiliation":"","apparentAge":"40s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional spiritual mastery\nAdvanced curse control\nAncestor communication\nCrossroads manipulation\nSpiritual defense\nExperienced mentorship","weaknesses":"Unresolved grief\nSuppressed rage\nProtectiveness toward Sax","combatStyle":["Tactical","Ritual-based","Binding-focused","Curse-based","Spirit-assisted"],"limitations":["Spiritual balance must be maintained"],"powerSource":["Chronoessence","Ancestor spirits","Loa","Spiritual crossroads"],"abilityNotes":"Voodoo in Aethelgard draws upon Chronoessence, ancestral spirits, Loa, nature, and places where the veil between realms is thin. Silas''s mastery makes him capable of maintaining spiritual equilibrium and opposing corruption such as the Shadow Blight. These same principles allow him to teach Kaelen structured spiritual methods for containing and grounding Umbral Genesis.","combatProfile":"Silas approaches conflict through control rather than simple destructive force. He uses spirits, curses, bindings, redirection, and manipulation of spiritual connections to weaken or neutralize opponents. His experience with the crossroads allows him to fight threats that operate across physical and spiritual boundaries.","weaponDetails":"","transformations":"","primaryAbilities":"Ancestor Magic\nSpirit Communion\nCrossroads Magic\nCurse-Weaving\nChronoessence Manipulation","secondaryAbilities":"Spirit Invocation\nSpiritual Binding\nCurse Redirection\nSpiritual Cleansing\nGris-Gris Creation\nRitual Magic\nSpiritual Protection","signatureTechniques":"Ancestor Communion\nCrossroads Invocation\nSpiritual Grounding\nCurse Binding\nCurse Redirection","transformationDetails":""},"is_public":false,"appearance":{"build":["Tall","Muscular","Broad-shouldered"],"nails":"","eyeHex":["Lilac — #B47AE8"],"height":"6''4\"","makeup":"","weight":"","hairHex":["Black — #111013"],"skinHex":["Deep Ebony — #3A2119"],"eyeColor":["Lilac"],"grooming":"Well-kept beard","skinTone":["Deep ebony"],"wardrobe":"Ritual robes\nLeather wraps\nLayered trousers\nLaced sandals","hairColor":["Black"],"hairStyle":"Long curls with a subtle undercut","accessories":"Bone necklaces\nFeather charms\nBeaded bracelets\nGris-gris charms\nRitual talismans","faceDetails":["Handsome angular face","Thick arched eyebrows","Full beard","Thin connected mustache"],"hairTexture":["4C","Curly"],"colorPalette":"Black — #111013\nDeep Brown — #3A2119\nLilac — #B47AE8\nBone Ivory — #D8C9AA\nDark Purple — #4A284F\nSpirit Green — #72C66A","dominantHand":"","outfitColors":"Black\nDark brown\nDeep purple\nBone ivory","alternateForm":"","clothingStyle":"Ancient spiritual attire combining practical wilderness clothing with ritual adornments. Bones, feathers, animal hides, beads, and intricate lacing visually reflect his connection to ancestral traditions and the spiritual crossroads.","appearanceNotes":"Silas normally presents himself with an easy, goofy smile that reinforces his relaxed and humorous persona. When that mask drops, his expression becomes gloomy and severe, with a blank stare, deep frown, visible rage, and an almost unhinged intensity revealing grief he has never completely healed from.","outfitMaterials":["Animal hide","Leather","Bone","Feathers","Beads","Woven cloth"],"postureMovement":["Relaxed","Confident","Intimidating when serious"],"signatureOutfit":"Layered dark ritual clothing with an open chest, intricate lacing, animal hides, bone adornments, feathers, beads, wraps, and weathered fabric.","distinguishingFeatures":["Voodoo-style tattoos"]},"created_at":"2026-09-25T17:31:02.583952+00:00","updated_at":"2026-09-25T17:31:02.583952+00:00","is_complete":false,"origin_lore":{"fears":["Losing Sax","Failing his family again","Spiritual imbalance","Shadow Blight corruption"],"goals":["Prepare Sax as a successor","Ground Kaelen''s power","Protect Moonwood Vail","Preserve spiritual equilibrium"],"beliefs":["Ancestor veneration","Harmony with spirits","Balance between realms","Chronoessence connects existence","Spiritual power requires responsibility"],"culture":["Moonwood Vail","Voodoo tradition"],"lineage":"","storyArc":"Silas''s outward humor conceals grief and rage that never fully disappeared after his family''s massacre. His relationship with Sax gives him a reason to remain emotionally connected to the living instead of surrendering himself completely to vengeance. Through mentoring Sax and Kaelen, his role evolves from survivor seeking strength into a guardian responsible for passing that strength forward.","backstory":"Silas eventually married and had a daughter while his brother married and had Sax. At thirty-one, Silas remained home reading while his family went out together. Captain Blackheart''s pirates attacked while searching for a powerful vampire relic and slaughtered Silas''s family. Silas discovered one-year-old Sax alive beneath his mother''s body. Consumed by grief and the need to protect his nephew, Silas devoted himself to Voodoo and eventually rose to become the Grand Voodoo Priest.","childhood":"Silas grew up in the slums of Moonwood Vail with his younger brother and their struggling mother. At thirteen, Silas and his ten-year-old brother vowed to escape poverty and give their mother a better life. Through years of odd jobs and saving, they moved her into a small cottage when Silas was seventeen.","lifestyle":["Spiritual training","Ancestor communion","Ritual practice","Mentoring","Crossroads guardianship"],"storyRole":"Silas serves as a major mentor and spiritual anchor within The Chronicles of Umbra. His mastery of Voodoo allows him to bridge the living world, ancestral realms, and the deeper forces surrounding Chronoessence. His knowledge becomes especially important when he begins teaching Kaelen how to ground the unstable power of Umbral Genesis.","birthplace":"Moonwood Vail","psychology":["Unresolved grief","Suppressed rage","Survivor''s guilt","Protective attachment to Sax","Humor masks emotional pain"],"motivations":["Protect Sax","Honor his family","Maintain spiritual balance","Defend the crossroads","Oppose the Shadow Blight","Avenge his family"],"personality":["Witty","Funny","Carefree","Protective","Strict","Demanding","Resilient","Vengeful"],"voiceSpeech":["Relaxed humor","Playful teasing","Strict teaching voice","Serious when necessary"],"likesDislikes":["Reading","Humor","Spiritual study","Protecting Sax","Pirates"],"majorLifeEvents":"Raised in Moonwood Vail slums\nVowed to escape poverty at thirteen\nMoved his mother from the slums\nMarried and became a father\nCaptain Blackheart''s pirate raid\nFound Sax alive after the massacre\nDevoted himself to Voodoo training\nBecame Grand Voodoo Priest\nBegan training Sax\nBegan mentoring Kaelen"},"canon_status":"concept","current_step":2,"portrait_url":null,"relationships":{"allies":"Sax\nKaelen","rivals":"","enemies":"Captain Blackheart","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Moonwood Vail","relationshipNotes":"Sax is Silas''s nephew and the only surviving member of his immediate family after Captain Blackheart''s raid. Silas raised, protected, and relentlessly trained him with the possibility that Sax may eventually succeed him as Grand Voodoo Priest. Silas later becomes Kaelen''s mentor, teaching him Voodoo principles to ground and contain Umbral Genesis."},"spoiler_level":"private","race_record_id":"c68d60d1-883a-4683-8000-a9cd9d0d4d2a","realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}','2026-09-25T17:32:48.29597+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('571ecc81-0b04-47cb-aa1b-543d81382eb9','studio_characters','2db0849d-a110-403b-a442-42bab2a31f6f','Gaius','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"2db0849d-a110-403b-a442-42bab2a31f6f","name":"Gaius","media":{"tbdFields":"","canonLocks":"","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"","productionNotes":"","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Gaius","race":"Elemental Dragon","alias":"The Sand Dragon","gender":"Male","titles":"Warden of the Wastes","subrace":"","summary":"Gaius is the Sand Dragon, born from the elemental union of Earth and Air. Calm, observant, and fiercely independent, he wanders the shifting deserts as a solitary warden. His power embodies erosion: the gradual reduction of even the strongest structures into countless moving grains.","heritage":"Indian + White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Warden of the Wastes","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shifting Sands","elementalHeritage":"Earth + Air"},"abilities":{"weapons":"","strengths":"Physical attack evasion\nArea control\nAttrition combat\nEnvironmental manipulation\nArmor erosion\nBody reformation","weaknesses":"","combatStyle":["Patient","Defensive","Attrition-based","Area control","Indirect"],"limitations":["Extreme heat fuses sand into glass"],"powerSource":["Earth","Air","Sand"],"abilityNotes":"Gaius can disperse his physical body into sand, allowing conventional physical attacks to pass through him. Extreme heat can fuse his sand into glass, which he can manipulate into cages, barriers, jagged formations, or shattered projectiles. His sand combines Earth''s physical matter with Air''s velocity.","combatProfile":"Gaius avoids brute-force exchanges and gradually controls the battlefield through sandstorms, erosion, blindness, suffocation, and friction. He can dissolve into billions of grains to evade physical attacks and reform elsewhere. His high-speed sand can gradually strip protective material from targets.","weaponDetails":"","transformations":"Sand Dragon Form","primaryAbilities":"Sand Manipulation\nErosion Manipulation\nSand Dissolution\nSandstorm Generation","secondaryAbilities":"Mirage Creation\nFriction Manipulation\nSuffocation\nGlass Creation\nBody Reformation","signatureTechniques":"Mirage & Dissolution\nSuffocation & Friction\nGlass Creation","transformationDetails":"Gaius becomes a massive dragon composed of compressed golden-brown sand, silica, and quartz. His scales continuously grind and shift like moving dunes, while portions of his wings and tail dissolve into a perpetual sandstorm. His crystalline gold eyes remain completely solid and motionless while the rest of his body constantly shifts."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Broad-shouldered"],"nails":"","eyeHex":["Golden Amber — #D89A32"],"height":"","makeup":"","weight":"","hairHex":["Black — #171313"],"skinHex":["Warm Brown — #9A6848"],"eyeColor":["Golden amber"],"grooming":"Natural","skinTone":["Warm medium-brown"],"wardrobe":"Layered desert wraps\nFlowing drapes\nLoose trousers\nFace wraps\nLeather waist layers","hairColor":["Black"],"hairStyle":"Tousled medium-length hair","accessories":"Gold earrings\nBronze arm cuffs\nLayered waist belts\nDesert face wrap","faceDetails":["Angular features","Defined jawline"],"hairTexture":["Wavy","Thick"],"colorPalette":"Sand — #D6B07A\nDune Gold — #C78B3B\nCopper — #9B5D2E\nDeep Brown — #4A3025\nDesert Cream — #E6D7BC","dominantHand":"","outfitColors":"Beige\nCopper\nDeep gold\nBrown","alternateForm":["Sand Dragon Form"],"clothingStyle":"Practical early-medieval desert attire designed for heat, wind, dust, and long-distance travel. Gaius favors loose layers that move naturally with the wind and can be rearranged for protection during sandstorms.","appearanceNotes":"His human design carries a distinctly nomadic desert silhouette with flowing layers and minimal rigid armor. His clothing should appear weathered and functional while retaining subtle gold ornamentation.","outfitMaterials":["Linen","Leather","Bronze","Gold"],"postureMovement":["Relaxed","Quiet","Fluid"],"signatureOutfit":"Layered desert wraps with flowing linen drapes, loose trousers, wrapped footwear, leather waist layers, and a protective face wrap. Gold and bronze accessories add restrained ornamentation without sacrificing mobility.","distinguishingFeatures":["Desert face wrap"]},"created_at":"2026-09-25T17:33:26.092803+00:00","updated_at":"2026-09-25T17:33:26.092803+00:00","is_complete":true,"origin_lore":{"fears":"","goals":["Guard the elemental borders","Preserve the wastes"],"beliefs":["Power does not require recognition","Change is inevitable"],"culture":"","lineage":"Primal Earth + Primal Air","storyArc":"","backstory":"Born to Terrax and Atherous, Gaius inherited the physical mass of Earth and the relentless velocity of Air. Their combined forces manifested as sand and erosion rather than solid stone or open wind. He eventually chose a solitary existence among the vast dunes, distancing himself from elemental family conflicts.","childhood":"","lifestyle":["Nomadic","Solitary","Desert wandering","Border guarding"],"storyRole":"Gaius serves as a quiet border guardian between the mortal world and the dangerous territories of the Primal Dragons. His isolation allows him to occupy a neutral position within volatile elemental family conflicts.","birthplace":"","psychology":["Values independence","Avoids family drama","Dislikes confinement","Prefers observation"],"motivations":["Protect the desert borders","Maintain independence","Prevent mortal trespassing"],"personality":["Calm","Observant","Independent","Reserved","Patient","Detached"],"voiceSpeech":["Quiet","Measured","Reserved"],"likesDislikes":["Likes solitude","Likes open deserts","Likes quiet","Dislikes loud egos","Dislikes confinement","Dislikes unnecessary conflict"],"majorLifeEvents":"Became Warden of the Wastes"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":"48066562-cd1c-4b72-8c29-399594efad38","workflow_status":"draft","family_record_id":"65ff1f49-c1fc-4599-93a6-fe6a49a4c4d5","faction_record_id":null}','2026-09-25T17:35:23.258044+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('bd0c1a16-6f55-4985-ad03-2a51a89c04b7','studio_characters','2db0849d-a110-403b-a442-42bab2a31f6f','Gaius','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"2db0849d-a110-403b-a442-42bab2a31f6f","name":"Gaius","media":{"tbdFields":"","canonLocks":"","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"","productionNotes":"","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Gaius","race":"Elemental Dragon","alias":"The Sand Dragon","gender":"Male","titles":"Warden of the Wastes","subrace":"","summary":"Gaius is the Sand Dragon, born from the elemental union of Earth and Air. Calm, observant, and fiercely independent, he wanders the shifting deserts as a solitary warden. His power embodies erosion: the gradual reduction of even the strongest structures into countless moving grains.","heritage":"Indian + White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Warden of the Wastes","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shifting Sands","elementalHeritage":"Earth + Air"},"abilities":{"weapons":"","strengths":"Physical attack evasion\nArea control\nAttrition combat\nEnvironmental manipulation\nArmor erosion\nBody reformation","weaknesses":"","combatStyle":["Patient","Defensive","Attrition-based","Area control","Indirect"],"limitations":["Extreme heat fuses sand into glass"],"powerSource":["Earth","Air","Sand"],"abilityNotes":"Gaius can disperse his physical body into sand, allowing conventional physical attacks to pass through him. Extreme heat can fuse his sand into glass, which he can manipulate into cages, barriers, jagged formations, or shattered projectiles. His sand combines Earth''s physical matter with Air''s velocity.","combatProfile":"Gaius avoids brute-force exchanges and gradually controls the battlefield through sandstorms, erosion, blindness, suffocation, and friction. He can dissolve into billions of grains to evade physical attacks and reform elsewhere. His high-speed sand can gradually strip protective material from targets.","weaponDetails":"","transformations":"Sand Dragon Form","primaryAbilities":"Sand Manipulation\nErosion Manipulation\nSand Dissolution\nSandstorm Generation","secondaryAbilities":"Mirage Creation\nFriction Manipulation\nSuffocation\nGlass Creation\nBody Reformation","signatureTechniques":"Mirage & Dissolution\nSuffocation & Friction\nGlass Creation","transformationDetails":"Gaius becomes a massive dragon composed of compressed golden-brown sand, silica, and quartz. His scales continuously grind and shift like moving dunes, while portions of his wings and tail dissolve into a perpetual sandstorm. His crystalline gold eyes remain completely solid and motionless while the rest of his body constantly shifts."},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Broad-shouldered"],"nails":"","eyeHex":["Golden Amber — #D89A32"],"height":"","makeup":"","weight":"","hairHex":["Black — #171313"],"skinHex":["Warm Brown — #9A6848"],"eyeColor":["Golden amber"],"grooming":"Natural","skinTone":["Warm medium-brown"],"wardrobe":"Layered desert wraps\nFlowing drapes\nLoose trousers\nFace wraps\nLeather waist layers","hairColor":["Black"],"hairStyle":"Tousled medium-length hair","accessories":"Gold earrings\nBronze arm cuffs\nLayered waist belts\nDesert face wrap","faceDetails":["Angular features","Defined jawline"],"hairTexture":["Wavy","Thick"],"colorPalette":"Sand — #D6B07A\nDune Gold — #C78B3B\nCopper — #9B5D2E\nDeep Brown — #4A3025\nDesert Cream — #E6D7BC","dominantHand":"","outfitColors":"Beige\nCopper\nDeep gold\nBrown","alternateForm":["Sand Dragon Form"],"clothingStyle":"Practical early-medieval desert attire designed for heat, wind, dust, and long-distance travel. Gaius favors loose layers that move naturally with the wind and can be rearranged for protection during sandstorms.","appearanceNotes":"His human design carries a distinctly nomadic desert silhouette with flowing layers and minimal rigid armor. His clothing should appear weathered and functional while retaining subtle gold ornamentation.","outfitMaterials":["Linen","Leather","Bronze","Gold"],"postureMovement":["Relaxed","Quiet","Fluid"],"signatureOutfit":"Layered desert wraps with flowing linen drapes, loose trousers, wrapped footwear, leather waist layers, and a protective face wrap. Gold and bronze accessories add restrained ornamentation without sacrificing mobility.","distinguishingFeatures":["Desert face wrap"]},"created_at":"2026-09-25T17:33:26.092803+00:00","updated_at":"2026-09-25T17:35:23.258044+00:00","is_complete":true,"origin_lore":{"fears":"","goals":["Guard the elemental borders","Preserve the wastes"],"beliefs":["Power does not require recognition","Change is inevitable"],"culture":"","lineage":"Primal Earth + Primal Air","storyArc":"","backstory":"Born to Terrax and Atherous, Gaius inherited the physical mass of Earth and the relentless velocity of Air. Their combined forces manifested as sand and erosion rather than solid stone or open wind. He eventually chose a solitary existence among the vast dunes, distancing himself from elemental family conflicts.","childhood":"","lifestyle":["Nomadic","Solitary","Desert wandering","Border guarding"],"storyRole":"Gaius serves as a quiet border guardian between the mortal world and the dangerous territories of the Primal Dragons. His isolation allows him to occupy a neutral position within volatile elemental family conflicts.","birthplace":"","psychology":["Values independence","Avoids family drama","Dislikes confinement","Prefers observation"],"motivations":["Protect the desert borders","Maintain independence","Prevent mortal trespassing"],"personality":["Calm","Observant","Independent","Reserved","Patient","Detached"],"voiceSpeech":["Quiet","Measured","Reserved"],"likesDislikes":["Likes solitude","Likes open deserts","Likes quiet","Dislikes loud egos","Dislikes confinement","Dislikes unnecessary conflict"],"majorLifeEvents":"Became Warden of the Wastes"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""},"spoiler_level":"private","race_record_id":"f6cff800-4029-4f02-b391-098583082feb","realm_record_id":"48066562-cd1c-4b72-8c29-399594efad38","workflow_status":"draft","family_record_id":"65ff1f49-c1fc-4599-93a6-fe6a49a4c4d5","faction_record_id":null}','2026-09-25T17:41:37.072067+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('ae2e326b-5a19-4032-b93c-2900114174d7','studio_characters','eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478','Venny''Claire','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478","name":"Venny''Claire","media":{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nCompact agile build\nNatural linen dress\nBraided leather waist cord\nLayered jewelry\nLeather sandals\nBlack werepanther form\nSilver right hind leg patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and black werepanther production sheet.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish her youthful face, warm brown skin, deep brown eyes, wild 4c hair, compact build, linen dress, layered jewelry, braided leather waist cord, and sandals. Werebeast references establish the sleek black werepanther design.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Venny''Claire","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Werepanther","summary":"Venny''Claire is one of King Kaelo''s children and the mirror counterpart of Venny''Macon. Playful, carefree, and highly curious, she embraces movement and instinct with natural confidence. Her exceptional awareness and agility make her a swift, perceptive presence who treats the world around her as something to explore.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional agility\nHigh speed\nHeightened awareness\nFast reflexes\nFluid movement\nAcrobatic mobility","weaknesses":"","combatStyle":["Agile","Acrobatic","Instinctive","Evasive","Speed-focused"],"limitations":"","powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"Her heightened senses provide a constant low-level stream of sensory information that guides her movements and gives her exceptional awareness of her surroundings.","combatProfile":"Venny''Claire relies on speed, agility, instinct, and constant sensory awareness rather than overwhelming physical force. Her compact werepanther form allows rapid directional changes, fluid evasive movement, and acrobatic attacks.","weaponDetails":"","transformations":"Sudo Form\nBlack Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Agility\nEnhanced Speed\nHeightened Senses","secondaryAbilities":"Enhanced Awareness\nEnhanced Reflexes\nAcrobatic Movement\nStealth","signatureTechniques":"","transformationDetails":"Venny''Claire''s full werebeast form is a sleek black werepanther with a deep, inky coat that seems to absorb light. Her smaller, compact body is built for speed, stealth, and acrobatic agility. Her only visible dire wolf trait is a silver patch of fur on her right hind leg. She moves with fluid grace and retains her playful curiosity and exceptional awareness."},"is_public":false,"appearance":{"build":["Compact","Lean","Agile"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Sleeveless linen dress\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord\nLayered necklaces\nBeaded jewelry\nGold earrings\nGold bracelet","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGold\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown\nGold","alternateForm":["Black Werepanther","Sudo Form"],"clothingStyle":"Light, practical clothing that allows unrestricted movement and suits the climate of Moonwood Vail.","appearanceNotes":"Venny''Claire closely mirrors Venny''Macon in facial structure, complexion, eyes, and hair. She is smaller and more compact than her brother, with a lighter frame suited to speed, agility, and acrobatic movement.","outfitMaterials":["Woven linen","Leather","Beads","Metal"],"postureMovement":["Relaxed posture","Fluid movement","Light-footed"],"signatureOutfit":"Simple sleeveless woven linen dress secured with a braided leather waist cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]},"created_at":"2026-09-25T17:42:10.890987+00:00","updated_at":"2026-09-25T17:42:10.890987+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"","backstory":"","childhood":"","lifestyle":"","storyRole":"Venny''Claire represents instinct, curiosity, and freedom of movement. Her natural confidence and heightened awareness contrast with Venny''Macon''s uncertainty, making the twins mirrors in appearance but opposites in how they approach their abilities.","birthplace":"","psychology":["Highly instinctive","Constantly aware","Lives in the moment"],"motivations":["Exploration","Curiosity"],"personality":["Playful","Carefree","Curious","Unserious","Mischievous","Observant"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Venny''Claire and Venny''Macon are mirror counterparts in appearance and temperament. Their shared features emphasize their connection, while her playful confidence and instinctive nature contrast with his reserved uncertainty."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"bbe46246-e94b-498d-9ab5-cae88e0804f7","faction_record_id":null}','2026-09-25T17:55:24.671441+00:00');
